[[nodiscard]] carto::core::Result<std::vector<std::string>>
parse_source_metadata_values(std::string_view text, std::size_t maximum_token_bytes,
    bool lowercase_ascii) {
    using ValuesResult = carto::core::Result<std::vector<std::string>>;
    const auto fail = [](std::string message) {
        return ValuesResult::failure(carto::core::Diagnostic(
            carto::core::ErrorCode::invalid_argument, std::move(message)));
    };
    if (text.empty()) return ValuesResult::success({});

    std::vector<std::string> values;
    std::size_t begin = 0U;
    while (begin <= text.size()) {
        const std::size_t end = text.find(',', begin);
        std::string_view value = text.substr(begin,
            end == std::string_view::npos ? text.size() - begin : end - begin);
        while (!value.empty() && std::isspace(static_cast<unsigned char>(value.front()))) {
            value.remove_prefix(1U);
        }
        while (!value.empty() && std::isspace(static_cast<unsigned char>(value.back()))) {
            value.remove_suffix(1U);
        }
        if (value.empty() || value.size() > maximum_token_bytes) {
            return fail("Source metadata entries must be nonempty and within their size limit.");
        }
        std::string canonical(value);
        if (lowercase_ascii) {
            for (char& character : canonical) {
                if (character >= 'A' && character <= 'Z') {
                    character = static_cast<char>(character + ('a' - 'A'));
                }
            }
        }
        values.push_back(std::move(canonical));
        if (end == std::string_view::npos) break;
        begin = end + 1U;
    }
    std::sort(values.begin(), values.end());
    if (std::adjacent_find(values.begin(), values.end()) != values.end()) {
        return fail("Source metadata entries must be unique.");
    }
    return ValuesResult::success(std::move(values));
}

[[nodiscard]] std::string join_source_metadata_values(
    const std::vector<std::string>& values) {
    std::string result;
    for (const auto& value : values) {
        if (!result.empty()) result += ", ";
        result += value;
    }
    return result;
}

void draw_mesh_thumbnail_raster(
    ImDrawList& draw,
    ImVec2 minimum,
    ImVec2 maximum,
    const carto::studio::MeshThumbnailRaster& raster) {
    const std::uint64_t pixel_count =
        static_cast<std::uint64_t>(raster.width) * raster.height;
    if (raster.width == 0U || raster.height == 0U ||
        raster.width > carto::studio::kMaxThumbnailRasterDimension ||
        raster.height > carto::studio::kMaxThumbnailRasterDimension ||
        pixel_count > 65'536ULL || pixel_count * 4ULL != raster.rgba8.size()) {
        return;
    }
    const float pixel_width = (maximum.x - minimum.x) /
        static_cast<float>(raster.width);
    const float pixel_height = (maximum.y - minimum.y) /
        static_cast<float>(raster.height);
    for (std::uint32_t y = 0U; y < raster.height; ++y) {
        std::uint32_t x = 0U;
        while (x < raster.width) {
            const std::size_t offset =
                (static_cast<std::size_t>(y) * raster.width + x) * 4U;
            const std::uint8_t alpha = raster.rgba8[offset + 3U];
            if (alpha == 0U) {
                ++x;
                continue;
            }
            const std::array<std::uint8_t, 4U> color{
                raster.rgba8[offset], raster.rgba8[offset + 1U],
                raster.rgba8[offset + 2U], alpha};
            const std::uint32_t begin = x++;
            while (x < raster.width) {
                const std::size_t next_offset =
                    (static_cast<std::size_t>(y) * raster.width + x) * 4U;
                if (!std::equal(color.begin(), color.end(),
                        raster.rgba8.data() + next_offset)) {
                    break;
                }
                ++x;
            }
            const ImVec2 rectangle_min{
                minimum.x + static_cast<float>(begin) * pixel_width,
                minimum.y + static_cast<float>(y) * pixel_height};
            const ImVec2 rectangle_max{
                minimum.x + static_cast<float>(x) * pixel_width,
                minimum.y + static_cast<float>(y + 1U) * pixel_height};
            draw.AddRectFilled(rectangle_min, rectangle_max,
                IM_COL32(color[0U], color[1U], color[2U], color[3U]));
        }
    }
}

template <std::size_t Size>
[[nodiscard]] bool set_source_metadata_input(
    std::array<char, Size>& destination, std::string_view value) {
    if (value.size() >= destination.size()) return false;
    destination.fill('\0');
    std::copy(value.begin(), value.end(), destination.begin());
    return true;
}

[[nodiscard]] std::optional<carto::project::MaterialGraphValueType>
material_graph_input_type(
    const carto::project::MaterialGraphNode& node,
    std::size_t input_index) noexcept {
    using carto::project::MaterialGraphNodeKind;
    using carto::project::MaterialGraphValueType;
    switch (node.kind) {
    case MaterialGraphNodeKind::texture_sample:
        if (input_index < 2U) return MaterialGraphValueType::scalar;
        break;
    case MaterialGraphNodeKind::add:
    case MaterialGraphNodeKind::multiply:
        if (input_index < 2U) return node.value_type;
        break;
    case MaterialGraphNodeKind::mix:
        if (input_index < 2U) return node.value_type;
        if (input_index == 2U) return MaterialGraphValueType::scalar;
        break;
    case MaterialGraphNodeKind::constant_scalar:
    case MaterialGraphNodeKind::constant_color:
    case MaterialGraphNodeKind::parameter_scalar:
    case MaterialGraphNodeKind::parameter_color:
    case MaterialGraphNodeKind::surface_input:
    case MaterialGraphNodeKind::unsupported:
        break;
    }
    return std::nullopt;
}

[[nodiscard]] const char* material_graph_value_type_name(
    carto::project::MaterialGraphValueType type) noexcept {
    switch (type) {
    case carto::project::MaterialGraphValueType::scalar: return "scalar";
    case carto::project::MaterialGraphValueType::color: return "color";
    case carto::project::MaterialGraphValueType::normal: return "normal";
    }
    return "unknown";
}

[[nodiscard]] std::wstring wide(const std::string& value) {
    return std::wstring(value.begin(), value.end());
}

[[nodiscard]] std::optional<std::string> system_font_path(const wchar_t* file_name) {
    std::array<wchar_t, MAX_PATH> windows_directory{};
    const UINT directory_length = GetWindowsDirectoryW(
        windows_directory.data(), static_cast<UINT>(windows_directory.size()));
    if (directory_length == 0U || directory_length >= windows_directory.size()) return std::nullopt;

    std::wstring path(windows_directory.data(), directory_length);
    if (!path.empty() && path.back() != L'\\') path.push_back(L'\\');
    path += L"Fonts\\";
    path += file_name;
    const DWORD attributes = GetFileAttributesW(path.c_str());
    if (attributes == INVALID_FILE_ATTRIBUTES || (attributes & FILE_ATTRIBUTE_DIRECTORY) != 0U) {
        return std::nullopt;
    }

    const int utf8_length = WideCharToMultiByte(
        CP_UTF8, WC_ERR_INVALID_CHARS, path.c_str(), static_cast<int>(path.size()),
        nullptr, 0, nullptr, nullptr);
    if (utf8_length <= 0) return std::nullopt;
    std::string utf8_path(static_cast<std::size_t>(utf8_length), '\0');
    if (WideCharToMultiByte(
            CP_UTF8, WC_ERR_INVALID_CHARS, path.c_str(), static_cast<int>(path.size()),
            utf8_path.data(), utf8_length, nullptr, nullptr) != utf8_length) {
        return std::nullopt;
    }
    return utf8_path;
}

[[nodiscard]] std::optional<std::string> preferred_system_font_path(
    std::initializer_list<const wchar_t*> file_names) {
    for (const wchar_t* file_name : file_names) {
        if (const auto path = system_font_path(file_name); path.has_value()) return path;
    }
    return std::nullopt;
}

void check_vk(VkResult result, const char* operation) {
    if (result != VK_SUCCESS) {
        throw std::runtime_error(std::string(operation) + " failed with Vulkan result " +
                                 std::to_string(static_cast<int>(result)));
    }
}

// Dear ImGui's docking Vulkan backend asks the platform layer for a surface
// per extra OS window; the Win32 backend supplies the HWND.
int create_imgui_vulkan_surface(
    ImGuiViewport* viewport,
    ImU64 instance_handle,
    const void* allocator_data,
    ImU64* surface_handle) {
    if (viewport == nullptr || viewport->PlatformHandleRaw == nullptr ||
        surface_handle == nullptr) {
        return static_cast<int>(VK_ERROR_INITIALIZATION_FAILED);
    }
    *surface_handle = 0U;
    VkWin32SurfaceCreateInfoKHR create_info{};
    create_info.sType = VK_STRUCTURE_TYPE_WIN32_SURFACE_CREATE_INFO_KHR;
    create_info.hinstance = GetModuleHandleW(nullptr);
    create_info.hwnd = static_cast<HWND>(viewport->PlatformHandleRaw);
    const auto instance = reinterpret_cast<VkInstance>(
        static_cast<std::uintptr_t>(instance_handle));
    VkSurfaceKHR surface = VK_NULL_HANDLE;
    const VkResult result = vkCreateWin32SurfaceKHR(
        instance, &create_info,
        static_cast<const VkAllocationCallbacks*>(allocator_data), &surface);
    if (result == VK_SUCCESS) {
        *surface_handle = static_cast<ImU64>(reinterpret_cast<std::uintptr_t>(surface));
    }
    return static_cast<int>(result);
}

class VulkanShell final {
public:
    ~VulkanShell() { shutdown(); }

    void initialize(HWND window) {
        window_ = window;
        create_instance();
        const auto surface_create_info = surface_info();
        check_vk(vkCreateWin32SurfaceKHR(instance_, &surface_create_info, nullptr, &surface_),
                 "vkCreateWin32SurfaceKHR");
        choose_device();
        create_device();
        create_command_objects();
        create_descriptor_pool();
        create_swapchain();

        ImGui_ImplVulkan_InitInfo init_info{};
        init_info.ApiVersion = VK_API_VERSION_1_1;
        init_info.Instance = instance_;
        init_info.PhysicalDevice = physical_device_;
        init_info.Device = device_;
        init_info.QueueFamily = queue_family_;
        init_info.Queue = queue_;
        init_info.DescriptorPool = descriptor_pool_;
        init_info.MinImageCount = image_count_;
        init_info.ImageCount = image_count_;
        init_info.PipelineInfoMain.MSAASamples = VK_SAMPLE_COUNT_1_BIT;
        init_info.PipelineInfoMain.RenderPass = render_pass_;
        if (!ImGui_ImplVulkan_Init(&init_info)) {
            throw std::runtime_error("Dear ImGui Vulkan backend initialization failed");
        }
        imgui_initialized_ = true;
    }

    void request_resize() noexcept { resize_pending_ = true; }

    [[nodiscard]] bool set_reference_image_texture(
        const carto::assets::DecodedRgba8Texture& decoded,
        std::string& diagnostic) {
        carto::assets::TextureSourceLimits texture_limits;
        texture_limits.max_pixels = 16'777'216ULL;
        const auto valid = decoded.validate(texture_limits);
        if (!valid || decoded.admission.stage !=
                carto::assets::TextureSourceStage::decoded ||
            decoded.admission.source.digest.is_zero()) {
            diagnostic = valid
                ? "reference viewport texture requires digest-bound decoded PNG, JPEG, or TGA pixels"
                : valid.error().message;
            return false;
        }
        if (!imgui_initialized_ || device_ == VK_NULL_HANDLE ||
            command_pool_ == VK_NULL_HANDLE || queue_ == VK_NULL_HANDLE) {
            diagnostic = "Vulkan renderer is unavailable for reference image upload";
            return false;
        }
        const std::string digest = decoded.admission.source.digest.hex();
        if (reference_image_texture_.has_value() &&
            reference_image_texture_->digest == digest &&
            reference_image_texture_->width == decoded.admission.width &&
            reference_image_texture_->height == decoded.admission.height) {
            return true;
        }
        std::optional<Rgba8Texture> candidate;
        if (!create_rgba8_texture(decoded.admission.width, decoded.admission.height,
                decoded.pixels, digest, candidate, "reference image", diagnostic)) {
            return false;
        }
        if (!publish_rgba8_texture(reference_image_texture_,
                retired_rgba8_textures_, candidate)) {
            if (candidate.has_value()) destroy_rgba8_texture(*candidate);
            diagnostic = "Unable to retain the prior reference texture through frame presentation";
            return false;
        }
        return true;
    }

    [[nodiscard]] bool set_scene_capture_texture(
        std::uint32_t width, std::uint32_t height,
        std::span<const std::uint8_t> pixels,
        const carto::assets::Sha256Digest& pixel_digest,
        std::string& diagnostic) {
        const std::uint64_t pixel_count = static_cast<std::uint64_t>(width) * height;
        if (width == 0U || height == 0U || pixel_count > 16'777'216ULL ||
            pixel_count * 4ULL != pixels.size() || pixel_digest.is_zero()) {
            diagnostic = "rendered scene capture has invalid RGBA8 pixels or identity";
            return false;
        }
        if (!imgui_initialized_ || device_ == VK_NULL_HANDLE ||
            command_pool_ == VK_NULL_HANDLE || queue_ == VK_NULL_HANDLE) {
            diagnostic = "Vulkan renderer is unavailable for scene capture upload";
            return false;
        }
        const std::string digest = pixel_digest.hex();
        if (scene_capture_texture_.has_value() &&
            scene_capture_texture_->digest == digest &&
            scene_capture_texture_->width == width &&
            scene_capture_texture_->height == height) {
            return true;
        }
        std::optional<Rgba8Texture> candidate;
        if (!create_rgba8_texture(width, height, pixels, digest, candidate,
                "scene capture", diagnostic)) {
            return false;
        }
        if (!publish_rgba8_texture(scene_capture_texture_,
                retired_rgba8_textures_, candidate)) {
            if (candidate.has_value()) destroy_rgba8_texture(*candidate);
            diagnostic = "Unable to retain the prior scene texture through frame presentation";
            return false;
        }
        return true;
    }

    [[nodiscard]] ImTextureID reference_image_texture_id() const noexcept {
        if (!reference_image_texture_.has_value() ||
            reference_image_texture_->descriptor == VK_NULL_HANDLE) {
            return ImTextureID_Invalid;
        }
        return to_imgui_texture_id(reference_image_texture_->descriptor);
    }

    [[nodiscard]] ImTextureID scene_capture_texture_id() const noexcept {
        if (!scene_capture_texture_.has_value() ||
            scene_capture_texture_->descriptor == VK_NULL_HANDLE) {
            return ImTextureID_Invalid;
        }
        return to_imgui_texture_id(scene_capture_texture_->descriptor);
    }

    [[nodiscard]] bool set_source_reimport_thumbnail_texture(
        std::size_t slot, const carto::studio::MeshThumbnailRaster& raster,
        std::string& diagnostic) {
        const std::uint64_t pixel_count =
            static_cast<std::uint64_t>(raster.width) * raster.height;
        if (slot >= source_reimport_thumbnail_textures_.size() ||
            raster.width == 0U || raster.height == 0U ||
            pixel_count > 65'536ULL || pixel_count * 4ULL != raster.rgba8.size() ||
            raster.pixel_digest.is_zero()) {
            diagnostic = "source reimport thumbnail has invalid bounded RGBA8 pixels";
            return false;
        }
        if (!imgui_initialized_ || device_ == VK_NULL_HANDLE ||
            command_pool_ == VK_NULL_HANDLE || queue_ == VK_NULL_HANDLE) {
            diagnostic = "Vulkan renderer is unavailable for source reimport thumbnail upload";
            return false;
        }
        auto& texture = source_reimport_thumbnail_textures_[slot];
        const std::string digest = raster.pixel_digest.hex();
        if (texture.has_value() && texture->digest == digest &&
            texture->width == raster.width && texture->height == raster.height) {
            return true;
        }
        std::optional<Rgba8Texture> candidate;
        if (!create_rgba8_texture(raster.width, raster.height, raster.rgba8,
                digest, candidate, "source reimport thumbnail", diagnostic)) {
            return false;
        }
        if (!publish_rgba8_texture(texture, retired_rgba8_textures_, candidate)) {
            if (candidate.has_value()) destroy_rgba8_texture(*candidate);
            diagnostic = "Unable to retain the prior source thumbnail through frame presentation";
            return false;
        }
        return true;
    }

    [[nodiscard]] ImTextureID source_reimport_thumbnail_texture_id(
        std::size_t slot) const noexcept {
        if (slot >= source_reimport_thumbnail_textures_.size() ||
            !source_reimport_thumbnail_textures_[slot].has_value() ||
            source_reimport_thumbnail_textures_[slot]->descriptor == VK_NULL_HANDLE) {
            return ImTextureID_Invalid;
        }
        return to_imgui_texture_id(
            source_reimport_thumbnail_textures_[slot]->descriptor);
    }

    void clear_reference_image_texture() noexcept {
        if (!reference_image_texture_.has_value()) return;
        static_cast<void>(retire_rgba8_texture(
            reference_image_texture_, retired_rgba8_textures_));
    }

    void clear_scene_capture_texture() noexcept {
        if (!scene_capture_texture_.has_value()) return;
        static_cast<void>(retire_rgba8_texture(
            scene_capture_texture_, retired_rgba8_textures_));
    }

    void clear_source_reimport_thumbnail_texture(std::size_t slot) noexcept {
        if (slot >= source_reimport_thumbnail_textures_.size()) return;
        static_cast<void>(retire_rgba8_texture(
            source_reimport_thumbnail_textures_[slot], retired_rgba8_textures_));
    }

    void render(ImDrawData* draw_data) {
        if (resize_pending_) {
            recreate_swapchain();
        }
        if (client_width() == 0 || client_height() == 0) {
            destroy_retired_rgba8_textures();
            return;
        }

        FrameContext& frame = frame_contexts_.at(current_frame_);
        check_vk(vkWaitForFences(device_, 1, &frame.fence, VK_TRUE, UINT64_MAX),
                 "vkWaitForFences frame context");

        std::uint32_t image_index = 0;
        const VkResult acquired = vkAcquireNextImageKHR(
            device_, swapchain_, UINT64_MAX, frame.image_available, VK_NULL_HANDLE, &image_index);
        if (acquired == VK_ERROR_OUT_OF_DATE_KHR) {
            resize_pending_ = true;
            destroy_retired_rgba8_textures();
            return;
        }
        if (acquired == VK_SUBOPTIMAL_KHR) resize_pending_ = true;
        check_vk(acquired, "vkAcquireNextImageKHR");
        if (image_fences_.at(image_index) != VK_NULL_HANDLE &&
            image_fences_.at(image_index) != frame.fence) {
            check_vk(vkWaitForFences(
                         device_, 1, &image_fences_.at(image_index), VK_TRUE, UINT64_MAX),
                     "vkWaitForFences swapchain image");
        }
        image_fences_.at(image_index) = frame.fence;
        check_vk(vkResetFences(device_, 1, &frame.fence), "vkResetFences");

        check_vk(vkResetCommandBuffer(frame.command_buffer, 0), "vkResetCommandBuffer");
        VkCommandBufferBeginInfo begin{};
        begin.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
        check_vk(vkBeginCommandBuffer(frame.command_buffer, &begin), "vkBeginCommandBuffer");

        VkClearValue clear_value{};
        clear_value.color.float32[0] = 0.035F;
        clear_value.color.float32[1] = 0.045F;
        clear_value.color.float32[2] = 0.060F;
        clear_value.color.float32[3] = 1.0F;
        const std::array<VkClearValue, 1> clear{clear_value};
        VkRenderPassBeginInfo pass{};
        pass.sType = VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO;
        pass.renderPass = render_pass_;
        pass.framebuffer = framebuffers_.at(image_index);
        pass.renderArea.offset = {0, 0};
        pass.renderArea.extent = {swapchain_width_, swapchain_height_};
        pass.clearValueCount = static_cast<std::uint32_t>(clear.size());
        pass.pClearValues = clear.data();
        vkCmdBeginRenderPass(frame.command_buffer, &pass, VK_SUBPASS_CONTENTS_INLINE);
        ImGui_ImplVulkan_RenderDrawData(draw_data, frame.command_buffer);
        vkCmdEndRenderPass(frame.command_buffer);
        check_vk(vkEndCommandBuffer(frame.command_buffer), "vkEndCommandBuffer");

        const VkPipelineStageFlags wait_stage = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
        VkSubmitInfo submit{};
        submit.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
        submit.waitSemaphoreCount = 1;
        submit.pWaitSemaphores = &frame.image_available;
        submit.pWaitDstStageMask = &wait_stage;
        submit.commandBufferCount = 1;
        submit.pCommandBuffers = &frame.command_buffer;
        submit.signalSemaphoreCount = 1;
        submit.pSignalSemaphores = &frame.render_finished;
        check_vk(vkQueueSubmit(queue_, 1, &submit, frame.fence), "vkQueueSubmit");

        VkPresentInfoKHR present{};
        present.sType = VK_STRUCTURE_TYPE_PRESENT_INFO_KHR;
        present.waitSemaphoreCount = 1;
        present.pWaitSemaphores = &frame.render_finished;
        present.swapchainCount = 1;
        present.pSwapchains = &swapchain_;
        present.pImageIndices = &image_index;
        const VkResult presented = vkQueuePresentKHR(queue_, &present);
        if (presented == VK_ERROR_OUT_OF_DATE_KHR || presented == VK_SUBOPTIMAL_KHR) {
            resize_pending_ = true;
        } else {
            check_vk(presented, "vkQueuePresentKHR");
        }
        // Instrument controls can replace textures after ImGui draw data has
        // captured their descriptors. Keep retired images alive until this
        // frame has been submitted and presented.
        destroy_retired_rgba8_textures();
        frame.frame_id = next_frame_id_++;
        current_frame_ = (current_frame_ + 1U) % frame_contexts_.size();
    }

private:
    struct FrameContext {
        VkCommandBuffer command_buffer = VK_NULL_HANDLE;
        VkFence fence = VK_NULL_HANDLE;
        VkSemaphore image_available = VK_NULL_HANDLE;
        VkSemaphore render_finished = VK_NULL_HANDLE;
        std::uint64_t frame_id = 0U;
    };

    struct Rgba8Texture {
        std::string digest;
        std::uint32_t width = 0U;
        std::uint32_t height = 0U;
        VkImage image = VK_NULL_HANDLE;
        VkDeviceMemory memory = VK_NULL_HANDLE;
        VkImageView view = VK_NULL_HANDLE;
        VkDescriptorSet descriptor = VK_NULL_HANDLE;
    };

    template <typename Descriptor>
    [[nodiscard]] static ImTextureID to_imgui_texture_id(
        Descriptor descriptor) noexcept {
        if constexpr (std::is_pointer_v<Descriptor>) {
            return static_cast<ImTextureID>(
                reinterpret_cast<std::uintptr_t>(descriptor));
        } else {
            return static_cast<ImTextureID>(descriptor);
        }
    }

    [[nodiscard]] std::optional<std::uint32_t> find_memory_type(
        std::uint32_t type_bits,
        VkMemoryPropertyFlags required,
        VkMemoryPropertyFlags* selected_flags = nullptr) const noexcept {
        VkPhysicalDeviceMemoryProperties properties{};
        vkGetPhysicalDeviceMemoryProperties(physical_device_, &properties);
        for (std::uint32_t index = 0U; index < properties.memoryTypeCount; ++index) {
            const auto flags = properties.memoryTypes[index].propertyFlags;
            if ((type_bits & (1U << index)) != 0U && (flags & required) == required) {
                if (selected_flags != nullptr) *selected_flags = flags;
                return index;
            }
        }
        return std::nullopt;
    }

    void destroy_rgba8_texture(Rgba8Texture& texture) noexcept {
        if (texture.descriptor != VK_NULL_HANDLE && imgui_initialized_) {
            ImGui_ImplVulkan_RemoveTexture(texture.descriptor);
        }
        texture.descriptor = VK_NULL_HANDLE;
        if (device_ != VK_NULL_HANDLE && texture.view != VK_NULL_HANDLE) {
            vkDestroyImageView(device_, texture.view, nullptr);
        }
        texture.view = VK_NULL_HANDLE;
        if (device_ != VK_NULL_HANDLE && texture.image != VK_NULL_HANDLE) {
            vkDestroyImage(device_, texture.image, nullptr);
        }
        texture.image = VK_NULL_HANDLE;
        if (device_ != VK_NULL_HANDLE && texture.memory != VK_NULL_HANDLE) {
            vkFreeMemory(device_, texture.memory, nullptr);
        }
        texture.memory = VK_NULL_HANDLE;
        texture.width = 0U;
        texture.height = 0U;
        texture.digest.clear();
    }

    [[nodiscard]] bool retire_rgba8_texture(
        std::optional<Rgba8Texture>& current,
        std::vector<Rgba8Texture>& retired) noexcept {
        if (!current.has_value()) return true;
        try {
            retired.emplace_back(std::move(*current));
        } catch (...) {
            // Leave the live handle owned and usable if retirement storage
            // cannot grow; never destroy a resource still referenced by draw data.
            return false;
        }
        current.reset();
        return true;
    }

    [[nodiscard]] bool publish_rgba8_texture(
        std::optional<Rgba8Texture>& current,
        std::vector<Rgba8Texture>& retired,
        std::optional<Rgba8Texture>& candidate) noexcept {
        if (!candidate.has_value() || !retire_rgba8_texture(current, retired)) {
            return false;
        }
        current.emplace(std::move(*candidate));
        candidate.reset();
        return true;
    }

    void destroy_retired_rgba8_textures() noexcept {
        if (retired_rgba8_textures_.empty()) return;
        if (device_ != VK_NULL_HANDLE) {
            static_cast<void>(vkDeviceWaitIdle(device_));
        }
        for (auto& texture : retired_rgba8_textures_) {
            destroy_rgba8_texture(texture);
        }
        retired_rgba8_textures_.clear();
    }

    [[nodiscard]] bool create_rgba8_texture(
        std::uint32_t width,
        std::uint32_t height,
        std::span<const std::uint8_t> pixels,
        const std::string& digest,
        std::optional<Rgba8Texture>& destination,
        std::string_view label,
        std::string& diagnostic) {
        if (destination.has_value()) {
            diagnostic = "RGBA8 " + std::string(label) +
                " upload destination must be empty until publication";
            return false;
        }
        VkPhysicalDeviceProperties device_properties{};
        vkGetPhysicalDeviceProperties(physical_device_, &device_properties);
        if (width > device_properties.limits.maxImageDimension2D ||
            height > device_properties.limits.maxImageDimension2D) {
            diagnostic = "RGBA8 " + std::string(label) +
                " exceeds this Vulkan device's 2D texture limit";
            return false;
        }
        VkFormatProperties format_properties{};
        vkGetPhysicalDeviceFormatProperties(
            physical_device_, VK_FORMAT_R8G8B8A8_UNORM, &format_properties);
        constexpr VkFormatFeatureFlags required_format_features =
            VK_FORMAT_FEATURE_SAMPLED_IMAGE_BIT | VK_FORMAT_FEATURE_TRANSFER_DST_BIT;
        if ((format_properties.optimalTilingFeatures & required_format_features) !=
            required_format_features) {
            diagnostic = "Vulkan device cannot sample an RGBA8 " + std::string(label) +
                " texture";
            return false;
        }
        if (vkDeviceWaitIdle(device_) != VK_SUCCESS) {
            diagnostic = "Vulkan device did not become idle before RGBA8 " +
                std::string(label) + " upload";
            return false;
        }

        Rgba8Texture candidate;
        candidate.digest = digest;
        candidate.width = width;
        candidate.height = height;
        VkBuffer staging_buffer = VK_NULL_HANDLE;
        VkDeviceMemory staging_memory = VK_NULL_HANDLE;
        VkCommandBuffer upload_command = VK_NULL_HANDLE;
        const auto cleanup_staging = [&]() {
            if (upload_command != VK_NULL_HANDLE && command_pool_ != VK_NULL_HANDLE) {
                vkFreeCommandBuffers(device_, command_pool_, 1U, &upload_command);
                upload_command = VK_NULL_HANDLE;
            }
            if (staging_buffer != VK_NULL_HANDLE) {
                vkDestroyBuffer(device_, staging_buffer, nullptr);
                staging_buffer = VK_NULL_HANDLE;
            }
            if (staging_memory != VK_NULL_HANDLE) {
                vkFreeMemory(device_, staging_memory, nullptr);
                staging_memory = VK_NULL_HANDLE;
            }
        };
        const auto fail = [&](std::string reason) {
            cleanup_staging();
            destroy_rgba8_texture(candidate);
            diagnostic = std::move(reason);
            return false;
        };

        const VkDeviceSize upload_size = static_cast<VkDeviceSize>(pixels.size());
        VkBufferCreateInfo buffer_info{};
        buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
        buffer_info.size = upload_size;
        buffer_info.usage = VK_BUFFER_USAGE_TRANSFER_SRC_BIT;
        buffer_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
        if (vkCreateBuffer(device_, &buffer_info, nullptr, &staging_buffer) != VK_SUCCESS) {
            return fail("Vulkan staging buffer creation failed for RGBA8 " + std::string(label));
        }
        VkMemoryRequirements staging_requirements{};
        vkGetBufferMemoryRequirements(device_, staging_buffer, &staging_requirements);
        VkMemoryPropertyFlags staging_flags = 0U;
        const auto staging_type = find_memory_type(staging_requirements.memoryTypeBits,
            VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT, &staging_flags);
        if (!staging_type.has_value()) {
            return fail("Vulkan device has no host-visible memory for RGBA8 " +
                std::string(label) + " upload");
        }
        VkMemoryAllocateInfo staging_allocation{};
        staging_allocation.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
        staging_allocation.allocationSize = staging_requirements.size;
        staging_allocation.memoryTypeIndex = *staging_type;
        if (vkAllocateMemory(device_, &staging_allocation, nullptr, &staging_memory) !=
                VK_SUCCESS ||
            vkBindBufferMemory(device_, staging_buffer, staging_memory, 0U) != VK_SUCCESS) {
            return fail("Vulkan staging memory allocation failed for RGBA8 " +
                std::string(label));
        }
        void* mapped = nullptr;
        const VkResult map_result = vkMapMemory(
            device_, staging_memory, 0U, VK_WHOLE_SIZE, 0U, &mapped);
        if (map_result != VK_SUCCESS) {
            return fail("Vulkan staging memory could not be mapped for RGBA8 " +
                std::string(label));
        }
        if (mapped == nullptr) {
            vkUnmapMemory(device_, staging_memory);
            return fail("Vulkan staging memory returned no RGBA8 " +
                std::string(label) + " mapping");
        }
        std::memcpy(mapped, pixels.data(), pixels.size());
        if ((staging_flags & VK_MEMORY_PROPERTY_HOST_COHERENT_BIT) == 0U) {
            VkMappedMemoryRange flush{};
            flush.sType = VK_STRUCTURE_TYPE_MAPPED_MEMORY_RANGE;
            flush.memory = staging_memory;
            flush.offset = 0U;
            flush.size = VK_WHOLE_SIZE;
            const VkResult flushed = vkFlushMappedMemoryRanges(device_, 1U, &flush);
            vkUnmapMemory(device_, staging_memory);
            if (flushed != VK_SUCCESS) {
                return fail("Vulkan staging memory flush failed for RGBA8 " +
                    std::string(label));
            }
        } else {
            vkUnmapMemory(device_, staging_memory);
        }

        VkImageCreateInfo image_info{};
        image_info.sType = VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO;
        image_info.imageType = VK_IMAGE_TYPE_2D;
        image_info.format = VK_FORMAT_R8G8B8A8_UNORM;
        image_info.extent = {candidate.width, candidate.height, 1U};
        image_info.mipLevels = 1U;
        image_info.arrayLayers = 1U;
        image_info.samples = VK_SAMPLE_COUNT_1_BIT;
        image_info.tiling = VK_IMAGE_TILING_OPTIMAL;
        image_info.usage = VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_SAMPLED_BIT;
        image_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
        image_info.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        if (vkCreateImage(device_, &image_info, nullptr, &candidate.image) != VK_SUCCESS) {
            return fail("Vulkan image creation failed for RGBA8 " + std::string(label));
        }
        VkMemoryRequirements image_requirements{};
        vkGetImageMemoryRequirements(device_, candidate.image, &image_requirements);
        const auto image_type = find_memory_type(image_requirements.memoryTypeBits,
            VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
        if (!image_type.has_value()) {
            return fail("Vulkan device has no device-local memory for RGBA8 " +
                std::string(label));
        }
        VkMemoryAllocateInfo image_allocation{};
        image_allocation.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
        image_allocation.allocationSize = image_requirements.size;
        image_allocation.memoryTypeIndex = *image_type;
        if (vkAllocateMemory(device_, &image_allocation, nullptr, &candidate.memory) !=
                VK_SUCCESS ||
            vkBindImageMemory(device_, candidate.image, candidate.memory, 0U) != VK_SUCCESS) {
            return fail("Vulkan image memory allocation failed for RGBA8 " +
                std::string(label));
        }
        VkImageViewCreateInfo view_info{};
        view_info.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
        view_info.image = candidate.image;
        view_info.viewType = VK_IMAGE_VIEW_TYPE_2D;
        view_info.format = VK_FORMAT_R8G8B8A8_UNORM;
        view_info.components = {VK_COMPONENT_SWIZZLE_IDENTITY, VK_COMPONENT_SWIZZLE_IDENTITY,
            VK_COMPONENT_SWIZZLE_IDENTITY, VK_COMPONENT_SWIZZLE_IDENTITY};
        view_info.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        view_info.subresourceRange.levelCount = 1U;
        view_info.subresourceRange.layerCount = 1U;
        if (vkCreateImageView(device_, &view_info, nullptr, &candidate.view) != VK_SUCCESS) {
            return fail("Vulkan image view creation failed for RGBA8 " + std::string(label));
        }

        VkCommandBufferAllocateInfo command_allocation{};
        command_allocation.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;
        command_allocation.commandPool = command_pool_;
        command_allocation.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        command_allocation.commandBufferCount = 1U;
        if (vkAllocateCommandBuffers(device_, &command_allocation, &upload_command) !=
            VK_SUCCESS) {
            return fail("Vulkan upload command allocation failed for RGBA8 " +
                std::string(label));
        }
        VkCommandBufferBeginInfo command_begin{};
        command_begin.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
        command_begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
        if (vkBeginCommandBuffer(upload_command, &command_begin) != VK_SUCCESS) {
            return fail("Vulkan upload command could not begin for RGBA8 " +
                std::string(label));
        }
        VkImageMemoryBarrier to_transfer{};
        to_transfer.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
        to_transfer.srcAccessMask = 0U;
        to_transfer.dstAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
        to_transfer.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        to_transfer.newLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
        to_transfer.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        to_transfer.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        to_transfer.image = candidate.image;
        to_transfer.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        to_transfer.subresourceRange.levelCount = 1U;
        to_transfer.subresourceRange.layerCount = 1U;
        vkCmdPipelineBarrier(upload_command, VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,
            VK_PIPELINE_STAGE_TRANSFER_BIT, 0U, 0U, nullptr, 0U, nullptr, 1U,
            &to_transfer);
        VkBufferImageCopy copy{};
        copy.imageSubresource.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        copy.imageSubresource.layerCount = 1U;
        copy.imageExtent = {candidate.width, candidate.height, 1U};
        vkCmdCopyBufferToImage(upload_command, staging_buffer, candidate.image,
            VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1U, &copy);
        VkImageMemoryBarrier to_sample{};
        to_sample.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
        to_sample.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
        to_sample.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
        to_sample.oldLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
        to_sample.newLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
        to_sample.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        to_sample.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        to_sample.image = candidate.image;
        to_sample.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        to_sample.subresourceRange.levelCount = 1U;
        to_sample.subresourceRange.layerCount = 1U;
        vkCmdPipelineBarrier(upload_command, VK_PIPELINE_STAGE_TRANSFER_BIT,
            VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT, 0U, 0U, nullptr, 0U, nullptr, 1U,
            &to_sample);
        if (vkEndCommandBuffer(upload_command) != VK_SUCCESS) {
            return fail("Vulkan upload command could not finish for RGBA8 " +
                std::string(label));
        }
        VkSubmitInfo upload_submit{};
        upload_submit.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
        upload_submit.commandBufferCount = 1U;
        upload_submit.pCommandBuffers = &upload_command;
        if (vkQueueSubmit(queue_, 1U, &upload_submit, VK_NULL_HANDLE) != VK_SUCCESS ||
            vkQueueWaitIdle(queue_) != VK_SUCCESS) {
            return fail("Vulkan texture upload failed for RGBA8 " + std::string(label));
        }
        cleanup_staging();
        candidate.descriptor = ImGui_ImplVulkan_AddTexture(
            candidate.view, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
        if (candidate.descriptor == VK_NULL_HANDLE) {
            return fail("Dear ImGui could not bind the RGBA8 " + std::string(label) + " texture");
        }
        destination.emplace(std::move(candidate));
        diagnostic.clear();
        return true;
    }

    static constexpr std::size_t kFrameContextCount = 3U;

    enum class PresentPolicy {
        performance,
        vsync,
        immediate,
    };

    [[nodiscard]] static PresentPolicy present_policy_from_environment() noexcept {
        const char* requested = std::getenv("CARTO_PRESENT_MODE");
        if (requested == nullptr) return PresentPolicy::performance;
        const std::string_view value(requested);
        if (value == "fifo" || value == "vsync") return PresentPolicy::vsync;
        if (value == "immediate" || value == "debug") return PresentPolicy::immediate;
        return PresentPolicy::performance;
    }

    [[nodiscard]] VkPresentModeKHR select_present_mode(
        const std::vector<VkPresentModeKHR>& supported) const {
        const auto has = [&supported](VkPresentModeKHR mode) {
            return std::find(supported.begin(), supported.end(), mode) != supported.end();
        };
        switch (present_policy_) {
        case PresentPolicy::performance:
            if (has(VK_PRESENT_MODE_MAILBOX_KHR)) return VK_PRESENT_MODE_MAILBOX_KHR;
            return VK_PRESENT_MODE_FIFO_KHR;
        case PresentPolicy::vsync:
            return VK_PRESENT_MODE_FIFO_KHR;
        case PresentPolicy::immediate:
            if (has(VK_PRESENT_MODE_IMMEDIATE_KHR)) return VK_PRESENT_MODE_IMMEDIATE_KHR;
            return VK_PRESENT_MODE_FIFO_KHR;
        }
        return VK_PRESENT_MODE_FIFO_KHR;
    }

    [[nodiscard]] VkWin32SurfaceCreateInfoKHR surface_info() const noexcept {
        VkWin32SurfaceCreateInfoKHR info{};
        info.sType = VK_STRUCTURE_TYPE_WIN32_SURFACE_CREATE_INFO_KHR;
        info.hinstance = GetModuleHandleW(nullptr);
        info.hwnd = window_;
        return info;
    }

    [[nodiscard]] std::uint32_t client_width() const noexcept {
        RECT rect{};
        GetClientRect(window_, &rect);
        return static_cast<std::uint32_t>(std::max<LONG>(0, rect.right - rect.left));
    }

    [[nodiscard]] std::uint32_t client_height() const noexcept {
        RECT rect{};
        GetClientRect(window_, &rect);
        return static_cast<std::uint32_t>(std::max<LONG>(0, rect.bottom - rect.top));
    }

    void create_instance() {
        const std::array<const char*, 2> extensions{
            VK_KHR_SURFACE_EXTENSION_NAME,
            VK_KHR_WIN32_SURFACE_EXTENSION_NAME,
        };
        VkApplicationInfo app{};
        app.sType = VK_STRUCTURE_TYPE_APPLICATION_INFO;
        app.pApplicationName = "Cartographer";
        app.applicationVersion = 1;
        app.pEngineName = "Cartographer";
        app.engineVersion = 1;
        app.apiVersion = VK_API_VERSION_1_1;
        VkInstanceCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;
        info.pApplicationInfo = &app;
        info.enabledExtensionCount = static_cast<std::uint32_t>(extensions.size());
        info.ppEnabledExtensionNames = extensions.data();
        check_vk(vkCreateInstance(&info, nullptr, &instance_), "vkCreateInstance");
    }

    void choose_device() {
        std::uint32_t count = 0;
        check_vk(vkEnumeratePhysicalDevices(instance_, &count, nullptr), "vkEnumeratePhysicalDevices");
        if (count == 0U) throw std::runtime_error("Vulkan reported no physical devices");
        std::vector<VkPhysicalDevice> devices(count);
        check_vk(vkEnumeratePhysicalDevices(instance_, &count, devices.data()), "vkEnumeratePhysicalDevices");
        for (VkPhysicalDevice device : devices) {
            std::uint32_t extension_count = 0U;
            check_vk(vkEnumerateDeviceExtensionProperties(
                         device, nullptr, &extension_count, nullptr),
                     "vkEnumerateDeviceExtensionProperties");
            std::vector<VkExtensionProperties> extensions(extension_count);
            check_vk(vkEnumerateDeviceExtensionProperties(
                         device, nullptr, &extension_count, extensions.data()),
                     "vkEnumerateDeviceExtensionProperties");
            const bool supports_swapchain = std::any_of(
                extensions.begin(), extensions.end(), [](const VkExtensionProperties& extension) {
                    return std::string_view(extension.extensionName) == VK_KHR_SWAPCHAIN_EXTENSION_NAME;
                });
            if (!supports_swapchain) continue;

            std::uint32_t queue_count = 0;
            vkGetPhysicalDeviceQueueFamilyProperties(device, &queue_count, nullptr);
            std::vector<VkQueueFamilyProperties> queues(queue_count);
            vkGetPhysicalDeviceQueueFamilyProperties(device, &queue_count, queues.data());
            for (std::uint32_t index = 0; index < queue_count; ++index) {
                VkBool32 present = VK_FALSE;
                check_vk(vkGetPhysicalDeviceSurfaceSupportKHR(device, index, surface_, &present),
                         "vkGetPhysicalDeviceSurfaceSupportKHR");
                if ((queues[index].queueFlags & VK_QUEUE_GRAPHICS_BIT) != 0U && present == VK_TRUE) {
                    physical_device_ = device;
                    queue_family_ = index;
                    return;
                }
            }
        }
        throw std::runtime_error("no Vulkan device exposes a graphics/present queue");
    }

    void create_device() {
        const float priority = 1.0F;
        VkDeviceQueueCreateInfo queue_info{};
        queue_info.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
        queue_info.queueFamilyIndex = queue_family_;
        queue_info.queueCount = 1;
        queue_info.pQueuePriorities = &priority;
        const std::array<const char*, 1> extensions{VK_KHR_SWAPCHAIN_EXTENSION_NAME};
        VkDeviceCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;
        info.queueCreateInfoCount = 1;
        info.pQueueCreateInfos = &queue_info;
        info.enabledExtensionCount = static_cast<std::uint32_t>(extensions.size());
        info.ppEnabledExtensionNames = extensions.data();
        check_vk(vkCreateDevice(physical_device_, &info, nullptr, &device_), "vkCreateDevice");
        vkGetDeviceQueue(device_, queue_family_, 0, &queue_);
    }

    void create_render_pass() {
        VkAttachmentDescription color{};
        color.format = swapchain_format_;
        color.samples = VK_SAMPLE_COUNT_1_BIT;
        color.loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
        color.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
        color.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        color.finalLayout = VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;
        VkAttachmentReference reference{};
        reference.attachment = 0;
        reference.layout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
        VkSubpassDescription subpass{};
        subpass.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
        subpass.colorAttachmentCount = 1;
        subpass.pColorAttachments = &reference;
        VkSubpassDependency dependency{};
        dependency.srcSubpass = VK_SUBPASS_EXTERNAL;
        dependency.dstSubpass = 0;
        dependency.srcStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
        dependency.dstStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
        dependency.dstAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
        VkRenderPassCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO;
        info.attachmentCount = 1;
        info.pAttachments = &color;
        info.subpassCount = 1;
        info.pSubpasses = &subpass;
        info.dependencyCount = 1;
        info.pDependencies = &dependency;
        check_vk(vkCreateRenderPass(device_, &info, nullptr, &render_pass_), "vkCreateRenderPass");
        render_pass_format_ = swapchain_format_;
    }

    void create_command_objects() {
        VkCommandPoolCreateInfo pool{};
        pool.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;
        pool.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
        pool.queueFamilyIndex = queue_family_;
        check_vk(vkCreateCommandPool(device_, &pool, nullptr, &command_pool_), "vkCreateCommandPool");
        VkCommandBufferAllocateInfo allocate{};
        allocate.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;
        allocate.commandPool = command_pool_;
        allocate.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        allocate.commandBufferCount = static_cast<std::uint32_t>(kFrameContextCount);
        std::array<VkCommandBuffer, kFrameContextCount> command_buffers{};
        check_vk(vkAllocateCommandBuffers(device_, &allocate, command_buffers.data()),
                 "vkAllocateCommandBuffers");

        VkSemaphoreCreateInfo semaphore{};
        semaphore.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO;
        VkFenceCreateInfo fence{};
        fence.sType = VK_STRUCTURE_TYPE_FENCE_CREATE_INFO;
        fence.flags = VK_FENCE_CREATE_SIGNALED_BIT;
        frame_contexts_.resize(kFrameContextCount);
        for (std::size_t index = 0U; index < frame_contexts_.size(); ++index) {
            auto& frame = frame_contexts_[index];
            frame.command_buffer = command_buffers[index];
            check_vk(vkCreateSemaphore(device_, &semaphore, nullptr, &frame.image_available),
                     "vkCreateSemaphore image_available");
            check_vk(vkCreateSemaphore(device_, &semaphore, nullptr, &frame.render_finished),
                     "vkCreateSemaphore render_finished");
            check_vk(vkCreateFence(device_, &fence, nullptr, &frame.fence),
                     "vkCreateFence frame context");
        }
    }

    void create_descriptor_pool() {
        const std::array<VkDescriptorPoolSize, 11> sizes{{
            {VK_DESCRIPTOR_TYPE_SAMPLER, 1000},
            {VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 1000},
            {VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE, 1000},
            {VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 1000},
            {VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER, 1000},
            {VK_DESCRIPTOR_TYPE_STORAGE_TEXEL_BUFFER, 1000},
            {VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 1000},
            {VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1000},
            {VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC, 1000},
            {VK_DESCRIPTOR_TYPE_STORAGE_BUFFER_DYNAMIC, 1000},
            {VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT, 1000},
        }};
        VkDescriptorPoolCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
        info.flags = VK_DESCRIPTOR_POOL_CREATE_FREE_DESCRIPTOR_SET_BIT;
        info.maxSets = 1000U * static_cast<std::uint32_t>(sizes.size());
        info.poolSizeCount = static_cast<std::uint32_t>(sizes.size());
        info.pPoolSizes = sizes.data();
        check_vk(vkCreateDescriptorPool(device_, &info, nullptr, &descriptor_pool_), "vkCreateDescriptorPool");
    }

    void select_swapchain_configuration() {
        VkSurfaceCapabilitiesKHR capabilities{};
        check_vk(vkGetPhysicalDeviceSurfaceCapabilitiesKHR(physical_device_, surface_, &capabilities),
                 "vkGetPhysicalDeviceSurfaceCapabilitiesKHR");
        std::uint32_t format_count = 0;
        check_vk(vkGetPhysicalDeviceSurfaceFormatsKHR(physical_device_, surface_, &format_count, nullptr),
                 "vkGetPhysicalDeviceSurfaceFormatsKHR");
        std::vector<VkSurfaceFormatKHR> formats(format_count);
        check_vk(vkGetPhysicalDeviceSurfaceFormatsKHR(physical_device_, surface_, &format_count, formats.data()),
                 "vkGetPhysicalDeviceSurfaceFormatsKHR");
        if (formats.empty()) throw std::runtime_error("Vulkan surface reported no swapchain formats");
        std::uint32_t present_mode_count = 0U;
        check_vk(vkGetPhysicalDeviceSurfacePresentModesKHR(
                     physical_device_, surface_, &present_mode_count, nullptr),
                 "vkGetPhysicalDeviceSurfacePresentModesKHR");
        std::vector<VkPresentModeKHR> present_modes(present_mode_count);
        check_vk(vkGetPhysicalDeviceSurfacePresentModesKHR(
                     physical_device_, surface_, &present_mode_count, present_modes.data()),
                 "vkGetPhysicalDeviceSurfacePresentModesKHR");
        swapchain_present_mode_ = select_present_mode(present_modes);
        swapchain_pre_transform_ = capabilities.currentTransform;
        VkSurfaceFormatKHR selected_format{};
        constexpr std::array<VkFormat, 4> preferred_formats{
            VK_FORMAT_B8G8R8A8_UNORM,
            VK_FORMAT_B8G8R8A8_SRGB,
            VK_FORMAT_R8G8B8A8_UNORM,
            VK_FORMAT_R8G8B8A8_SRGB,
        };
        for (const VkFormat preferred : preferred_formats) {
            const auto format = std::find_if(
                formats.begin(), formats.end(), [preferred](const VkSurfaceFormatKHR& candidate) {
                    return candidate.format == preferred;
                });
            if (format != formats.end()) {
                selected_format = *format;
                break;
            }
        }
        if (selected_format.format == VK_FORMAT_UNDEFINED) {
            selected_format = formats.front();
        }
        swapchain_format_ = selected_format.format;
        swapchain_color_space_ = selected_format.colorSpace;
        VkExtent2D extent = capabilities.currentExtent;
        if (extent.width == std::numeric_limits<std::uint32_t>::max()) {
            extent = {client_width(), client_height()};
        }
        extent.width = std::clamp(extent.width, capabilities.minImageExtent.width, capabilities.maxImageExtent.width);
        extent.height = std::clamp(extent.height, capabilities.minImageExtent.height, capabilities.maxImageExtent.height);
        swapchain_width_ = extent.width;
        swapchain_height_ = extent.height;
        image_count_ = capabilities.minImageCount + 1U;
        if (capabilities.maxImageCount != 0U) image_count_ = std::min(image_count_, capabilities.maxImageCount);
        if (image_count_ < 2U) {
            throw std::runtime_error("desktop shell requires at least two swapchain images");
        }
    }

    void create_swapchain() {
        select_swapchain_configuration();
        if (render_pass_ == VK_NULL_HANDLE || render_pass_format_ != swapchain_format_) {
            if (render_pass_ != VK_NULL_HANDLE) {
                vkDestroyRenderPass(device_, render_pass_, nullptr);
                render_pass_ = VK_NULL_HANDLE;
            }
            create_render_pass();
        }

        VkSwapchainCreateInfoKHR info{};
        info.sType = VK_STRUCTURE_TYPE_SWAPCHAIN_CREATE_INFO_KHR;
        info.surface = surface_;
        info.minImageCount = image_count_;
        info.imageFormat = swapchain_format_;
        info.imageColorSpace = swapchain_color_space_;
        info.imageExtent = {swapchain_width_, swapchain_height_};
        info.imageArrayLayers = 1;
        info.imageUsage = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
        info.imageSharingMode = VK_SHARING_MODE_EXCLUSIVE;
        info.preTransform = swapchain_pre_transform_;
        info.compositeAlpha = VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR;
        info.presentMode = swapchain_present_mode_;
        info.clipped = VK_TRUE;
        check_vk(vkCreateSwapchainKHR(device_, &info, nullptr, &swapchain_), "vkCreateSwapchainKHR");

        std::uint32_t actual_count = 0;
        check_vk(vkGetSwapchainImagesKHR(device_, swapchain_, &actual_count, nullptr), "vkGetSwapchainImagesKHR");
        images_.resize(actual_count);
        check_vk(vkGetSwapchainImagesKHR(device_, swapchain_, &actual_count, images_.data()), "vkGetSwapchainImagesKHR");
        image_views_.resize(images_.size());
        framebuffers_.resize(images_.size());
        image_fences_.assign(images_.size(), VK_NULL_HANDLE);
        for (std::size_t index = 0; index < images_.size(); ++index) {
            VkImageViewCreateInfo view{};
            view.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
            view.image = images_[index];
            view.viewType = VK_IMAGE_VIEW_TYPE_2D;
            view.format = swapchain_format_;
            view.components = {VK_COMPONENT_SWIZZLE_IDENTITY, VK_COMPONENT_SWIZZLE_IDENTITY,
                               VK_COMPONENT_SWIZZLE_IDENTITY, VK_COMPONENT_SWIZZLE_IDENTITY};
            view.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
            view.subresourceRange.levelCount = 1;
            view.subresourceRange.layerCount = 1;
            check_vk(vkCreateImageView(device_, &view, nullptr, &image_views_[index]), "vkCreateImageView");
            VkFramebufferCreateInfo framebuffer{};
            framebuffer.sType = VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO;
            framebuffer.renderPass = render_pass_;
            framebuffer.attachmentCount = 1;
            framebuffer.pAttachments = &image_views_[index];
            framebuffer.width = swapchain_width_;
            framebuffer.height = swapchain_height_;
            framebuffer.layers = 1;
            check_vk(vkCreateFramebuffer(device_, &framebuffer, nullptr, &framebuffers_[index]), "vkCreateFramebuffer");
        }
        resize_pending_ = false;
    }

    void recreate_swapchain() {
        if (client_width() == 0 || client_height() == 0) return;
        check_vk(vkDeviceWaitIdle(device_), "vkDeviceWaitIdle resize");
        for (VkFramebuffer framebuffer : framebuffers_) vkDestroyFramebuffer(device_, framebuffer, nullptr);
        for (VkImageView view : image_views_) vkDestroyImageView(device_, view, nullptr);
        framebuffers_.clear();
        image_views_.clear();
        images_.clear();
        vkDestroySwapchainKHR(device_, swapchain_, nullptr);
        swapchain_ = VK_NULL_HANDLE;
        create_swapchain();
        ImGui_ImplVulkan_SetMinImageCount(image_count_);
    }

public:
    void shutdown() noexcept {
        if (device_ != VK_NULL_HANDLE) {
            vkDeviceWaitIdle(device_);
            if (imgui_initialized_) {
                if (reference_image_texture_.has_value()) {
                    destroy_rgba8_texture(*reference_image_texture_);
                    reference_image_texture_.reset();
                }
                if (scene_capture_texture_.has_value()) {
                    destroy_rgba8_texture(*scene_capture_texture_);
                    scene_capture_texture_.reset();
                }
                for (auto& texture : source_reimport_thumbnail_textures_) {
                    if (texture.has_value()) {
                        destroy_rgba8_texture(*texture);
                        texture.reset();
                    }
                }
                destroy_retired_rgba8_textures();
                ImGui_ImplVulkan_Shutdown();
                imgui_initialized_ = false;
            }
            for (VkFramebuffer framebuffer : framebuffers_) vkDestroyFramebuffer(device_, framebuffer, nullptr);
            for (VkImageView view : image_views_) vkDestroyImageView(device_, view, nullptr);
            if (swapchain_ != VK_NULL_HANDLE) vkDestroySwapchainKHR(device_, swapchain_, nullptr);
            if (descriptor_pool_ != VK_NULL_HANDLE) vkDestroyDescriptorPool(device_, descriptor_pool_, nullptr);
            for (auto& frame : frame_contexts_) {
                if (frame.fence != VK_NULL_HANDLE) vkDestroyFence(device_, frame.fence, nullptr);
                if (frame.image_available != VK_NULL_HANDLE) {
                    vkDestroySemaphore(device_, frame.image_available, nullptr);
                }
                if (frame.render_finished != VK_NULL_HANDLE) {
                    vkDestroySemaphore(device_, frame.render_finished, nullptr);
                }
            }
            if (command_pool_ != VK_NULL_HANDLE) vkDestroyCommandPool(device_, command_pool_, nullptr);
            if (render_pass_ != VK_NULL_HANDLE) vkDestroyRenderPass(device_, render_pass_, nullptr);
            vkDestroyDevice(device_, nullptr);
            device_ = VK_NULL_HANDLE;
        }
        if (surface_ != VK_NULL_HANDLE && instance_ != VK_NULL_HANDLE) {
            vkDestroySurfaceKHR(instance_, surface_, nullptr);
            surface_ = VK_NULL_HANDLE;
        }
        if (instance_ != VK_NULL_HANDLE) vkDestroyInstance(instance_, nullptr);
        instance_ = VK_NULL_HANDLE;
        frame_contexts_.clear();
        image_fences_.clear();
    }

private:
    HWND window_ = nullptr;
    VkInstance instance_ = VK_NULL_HANDLE;
    VkSurfaceKHR surface_ = VK_NULL_HANDLE;
    VkPhysicalDevice physical_device_ = VK_NULL_HANDLE;
    VkDevice device_ = VK_NULL_HANDLE;
    VkQueue queue_ = VK_NULL_HANDLE;
    std::uint32_t queue_family_ = 0;
    VkSwapchainKHR swapchain_ = VK_NULL_HANDLE;
    VkFormat swapchain_format_ = VK_FORMAT_B8G8R8A8_UNORM;
    VkColorSpaceKHR swapchain_color_space_ = VK_COLOR_SPACE_SRGB_NONLINEAR_KHR;
    VkPresentModeKHR swapchain_present_mode_ = VK_PRESENT_MODE_FIFO_KHR;
    VkSurfaceTransformFlagBitsKHR swapchain_pre_transform_ = VK_SURFACE_TRANSFORM_IDENTITY_BIT_KHR;
    std::uint32_t swapchain_width_ = 0;
    std::uint32_t swapchain_height_ = 0;
    std::uint32_t image_count_ = 2;
    std::vector<VkImage> images_;
    std::vector<VkImageView> image_views_;
    std::vector<VkFramebuffer> framebuffers_;
    VkRenderPass render_pass_ = VK_NULL_HANDLE;
    VkFormat render_pass_format_ = VK_FORMAT_UNDEFINED;
    VkCommandPool command_pool_ = VK_NULL_HANDLE;
    VkDescriptorPool descriptor_pool_ = VK_NULL_HANDLE;
    std::vector<FrameContext> frame_contexts_;
    std::vector<VkFence> image_fences_;
    std::optional<Rgba8Texture> reference_image_texture_;
    std::optional<Rgba8Texture> scene_capture_texture_;
    std::array<std::optional<Rgba8Texture>, 2U>
        source_reimport_thumbnail_textures_;
    std::vector<Rgba8Texture> retired_rgba8_textures_;
    std::size_t current_frame_ = 0U;
    std::uint64_t next_frame_id_ = 0U;
    PresentPolicy present_policy_ = present_policy_from_environment();
    bool imgui_initialized_ = false;
    bool resize_pending_ = false;
};

