struct BotanicalRuntimeTaskResult {
    std::optional<carto::runtime_api::JobReceipt> job;
    std::vector<std::uint8_t> output;
    std::string expected_organization_scope;
    std::string error;
};

enum class BotanicalRuntimeOperation : std::uint8_t { submit, refresh };

BotanicalRuntimeTaskResult run_botanical_runtime_operation(
    BotanicalRuntimeOperation operation,
    carto::runtime_api::Config config,
    carto::botanical::Source source,
    std::string justification,
    std::string request_id,
    std::optional<carto::runtime_api::JobReceipt> prior_job) {
    BotanicalRuntimeTaskResult result;
    if (const auto configured = config.validate(); !configured) {
        result.error = configured.error().message;
        return result;
    }
    result.expected_organization_scope = config.organization;
    carto::runtime_api::Client client(std::move(config),
        carto::runtime_api::make_native_transport());
    if (operation == BotanicalRuntimeOperation::submit) {
        const auto serialized = source.serialize();
        auto submitted = client.submit_botanical_source(source.identity,
            source.revision, serialized, justification, request_id);
        if (!submitted) {
            result.error = submitted.error().message;
            return result;
        }
        result.job = std::move(submitted).value();
        return result;
    }
    if (!prior_job.has_value()) {
        result.error = "There is no submitted private botanical job to refresh.";
        return result;
    }
    auto refreshed = client.get_job(*prior_job);
    if (!refreshed) {
        result.error = refreshed.error().message;
        return result;
    }
    result.job = std::move(refreshed).value();
    if (result.job->status == "succeeded") {
        auto downloaded = client.download_output(*result.job);
        if (!downloaded) {
            result.error = downloaded.error().message;
            return result;
        }
        result.output = std::move(downloaded).value();
    }
    return result;
}


