    bool route_native_key(const carto::ui::NativeKeyEvent& event) {
        if (ImGui::GetCurrentContext() != nullptr && ImGui::GetIO().WantTextInput) {
            return false;
        }
        const auto shortcut = carto::ui::shortcut_for_native_key(event);
        if (!shortcut.has_value()) return false;
        if (!event.repeat) {
            if (*shortcut == carto::ui::Shortcut::save) {
                static_cast<void>(save_project(ui.snapshot()));
            } else {
                const auto routed = ui.handle_shortcut(*shortcut);
                if (!routed) {
                    action_feedback = routed.error().message;
                    action_feedback_error = true;
                }
            }
        }
        return true;
    }

    bool native_pointer_viewport_position(
        const carto::ui::NativePointerEvent& event,
        carto::core::Vec2d& position) const {
        // ImGui's main viewport uses client-space coordinates in this
        // single-window shell. Native pointer events already carry client
        // coordinates; promoting them to desktop coordinates makes every
        // viewport hit test miss by the outer window offset.
        position = {static_cast<double>(event.x), static_cast<double>(event.y)};
        return position.finite();
    }

    [[nodiscard]] std::optional<carto::core::Vec2d> viewport_screen_to_ground(
        carto::core::Vec2d screen_position) const {
        if (!screen_position.finite() || !native_viewport_hits.valid) return std::nullopt;
        const carto::core::Vec2d viewport_origin{
            native_viewport_hits.screen_origin.x, native_viewport_hits.screen_origin.y};
        const carto::core::Vec2d viewport_extent{
            native_viewport_hits.extent.x, native_viewport_hits.extent.y};
        if (!perspective_camera_active) {
            const auto world = work_surface_camera.screen_to_world(
                screen_position, viewport_origin, viewport_extent);
            return world ? std::optional<carto::core::Vec2d>{world.value()} : std::nullopt;
        }
        const auto ray = perspective_camera.ray_for_pixel(
            screen_position - viewport_origin, viewport_extent);
        if (!ray || std::abs(ray.value().direction.y) <= 1.0e-10) return std::nullopt;
        const double distance = -ray.value().origin.y / ray.value().direction.y;
        if (!std::isfinite(distance) || distance < 0.0) return std::nullopt;
        const carto::core::Vec3d hit = ray.value().origin +
            ray.value().direction * distance;
        if (!hit.finite()) return std::nullopt;
        return carto::core::Vec2d{hit.x, hit.z};
    }

    [[nodiscard]] bool viewport_camera_matches(
        bool expected_perspective,
        const carto::editor::EditorCamera& expected_perspective_camera,
        const carto::editor::WorkSurfaceCamera& expected_plan_camera) const noexcept {
        return carto::studio::viewport_camera_state_matches(
            perspective_camera_active, perspective_camera, work_surface_camera,
            expected_perspective, expected_perspective_camera, expected_plan_camera);
    }

    [[nodiscard]] bool viewport_surface_frontmost_at(
        carto::core::Vec2d screen_position,
        carto::scene::ObjectId expected_object,
        std::uint64_t expected_generation,
        carto::core::Revision expected_revision,
        const ImRect& expected_viewport,
        std::string& diagnostic) const {
        if (!perspective_camera_active) return true;
        if (!screen_position.finite() || !expected_object ||
            !native_viewport_hits.valid || !native_viewport_hits.interactive ||
            native_viewport_hits.sculpt_triangles_truncated ||
            native_viewport_hits.project_generation != expected_generation ||
            native_viewport_hits.project_revision != expected_revision) {
            diagnostic = "Perspective surface hit data is stale, incomplete, or invalid.";
            return false;
        }
        const ImRect current_viewport(
            native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        if (current_viewport.Min.x != expected_viewport.Min.x ||
            current_viewport.Min.y != expected_viewport.Min.y ||
            current_viewport.Max.x != expected_viewport.Max.x ||
            current_viewport.Max.y != expected_viewport.Max.y) {
            diagnostic = "Perspective surface capture cancelled because the viewport changed.";
            return false;
        }
        const auto hit = carto::ui::resolve_frontmost_viewport_surface(
            native_viewport_hits.sculpt_triangles, screen_position, true);
        if (!hit) {
            diagnostic = hit.error().message;
            return false;
        }
        if (hit.value().status == carto::ui::ProjectedSurfaceHitStatus::ambiguous) {
            diagnostic = "Perspective surface hit is ambiguous across overlapping visible objects.";
            return false;
        }
        if (hit.value().status != carto::ui::ProjectedSurfaceHitStatus::hit) {
            diagnostic = "The selected source surface is not visible at this screen position.";
            return false;
        }
        if (hit.value().object != expected_object) {
            diagnostic = "Another visible mesh is in front of the selected source surface.";
            return false;
        }
        return true;
    }

    [[nodiscard]] bool viewport_surface_segment_frontmost(
        carto::core::Vec2d start,
        carto::core::Vec2d end,
        carto::scene::ObjectId expected_object,
        std::uint64_t expected_generation,
        carto::core::Revision expected_revision,
        const ImRect& expected_viewport,
        std::string& diagnostic) const {
        if (!perspective_camera_active) return true;
        if (!start.finite() || !end.finite() || !expected_object) {
            diagnostic = "Perspective stroke segment is invalid.";
            return false;
        }
        const std::size_t triangle_count = native_viewport_hits.sculpt_triangles.size();
        const auto intervals = carto::studio::perspective_stroke_segment_intervals(
            start, end, triangle_count);
        if (!intervals) {
            diagnostic = intervals.error().message;
            return false;
        }
        const auto delta = end - start;
        for (std::size_t index = 1U; index < intervals.value(); ++index) {
            const double along = static_cast<double>(index) /
                static_cast<double>(intervals.value());
            std::string sample_diagnostic;
            if (!viewport_surface_frontmost_at(
                    start + (end - start) * along, expected_object,
                    expected_generation, expected_revision,
                    expected_viewport, sample_diagnostic)) {
                diagnostic = std::move(sample_diagnostic);
                return false;
            }
        }
        return true;
    }

    [[nodiscard]] bool viewport_edge_frontmost_at(
        const carto::ui::ProjectedEdgePickCandidate& edge,
        carto::core::Vec2d screen_position,
        std::uint64_t expected_generation,
        carto::core::Revision expected_revision,
        const ImRect& expected_viewport,
        std::string& diagnostic) const {
        if (!perspective_camera_active) return true;
        if (!edge.object || edge.edge.value == 0U || !screen_position.finite() ||
            !native_viewport_hits.valid || !native_viewport_hits.interactive ||
            native_viewport_hits.sculpt_triangles_truncated ||
            native_viewport_hits.project_generation != expected_generation ||
            native_viewport_hits.project_revision != expected_revision ||
            !edge.perspective_correct ||
            !std::isfinite(edge.camera_depth[0U]) ||
            !std::isfinite(edge.camera_depth[1U])) {
            diagnostic = "Perspective edge hit data is stale, incomplete, or invalid.";
            return false;
        }
        const ImRect current_viewport(
            native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        if (current_viewport.Min.x != expected_viewport.Min.x ||
            current_viewport.Min.y != expected_viewport.Min.y ||
            current_viewport.Max.x != expected_viewport.Max.x ||
            current_viewport.Max.y != expected_viewport.Max.y) {
            diagnostic = "Perspective edge pick cancelled because the viewport changed.";
            return false;
        }
        const carto::core::Vec2d delta = edge.second - edge.first;
        const double length_squared = delta.length_squared();
        if (!std::isfinite(length_squared) || length_squared <= 1.0e-18) {
            diagnostic = "Perspective edge hit data is degenerate.";
            return false;
        }
        const double along = std::clamp(
            carto::core::dot(screen_position - edge.first, delta) / length_squared,
            0.0, 1.0);
        const carto::core::Vec2d surface_point = edge.first + delta * along;
        const auto surface = carto::ui::resolve_frontmost_viewport_surface(
            native_viewport_hits.sculpt_triangles, surface_point, true);
        if (!surface) {
            diagnostic = surface.error().message;
            return false;
        }
        if (surface.value().status != carto::ui::ProjectedSurfaceHitStatus::hit ||
            surface.value().object != edge.object) {
            diagnostic = "The selected edge is not on the frontmost visible surface.";
            return false;
        }

        const auto edge_depth = carto::studio::perspective_edge_camera_depth(
            edge.camera_depth[0U], edge.camera_depth[1U], along);
        if (!edge_depth) {
            diagnostic = edge_depth.error().message;
            return false;
        }
        const auto frontmost = carto::studio::perspective_edge_is_frontmost(
            edge_depth.value(), surface.value().camera_depth);
        if (!frontmost) {
            diagnostic = frontmost.error().message;
            return false;
        }
        if (!frontmost.value()) {
            diagnostic = "The selected edge is occluded by a nearer visible surface.";
            return false;
        }
        return true;
    }

    bool condition_gizmo_local_delta(
        const NativeConditionGizmoHandle& handle,
        carto::core::Vec2d screen_position,
        carto::core::Vec3d& local_delta) const {
        const auto world = viewport_screen_to_ground(screen_position);
        if (!world) return false;
        const auto inverse_rotate = [](carto::core::Quaternion rotation,
                                       carto::core::Vec3d value) {
            const auto normalized = rotation.normalized();
            return carto::core::Quaternion{
                -normalized.x, -normalized.y, -normalized.z, normalized.w}.rotate(value);
        };
        const auto divide_scale = [](carto::core::Vec3d value,
                                     carto::core::Vec3d scale) -> std::optional<carto::core::Vec3d> {
            constexpr double kMinScale = 1.0e-9;
            if (!scale.finite() || std::abs(scale.x) < kMinScale ||
                std::abs(scale.y) < kMinScale || std::abs(scale.z) < kMinScale) {
                return std::nullopt;
            }
            return carto::core::Vec3d{
                value.x / scale.x, value.y / scale.y, value.z / scale.z};
        };
        const auto center = world_point(handle.owner_world,
            handle.local_transform.translation);
        const carto::core::Vec3d world_delta{
            world->x - center.x, 0.0, world->y - center.z};
        const auto parent_delta = divide_scale(
            inverse_rotate(handle.owner_world.rotation, world_delta),
            handle.owner_world.scale);
        if (!parent_delta) return false;
        const auto local_unscaled = inverse_rotate(handle.local_transform.rotation, *parent_delta);
        const auto local = divide_scale(local_unscaled, handle.local_transform.scale);
        if (!local || !local->finite()) return false;
        local_delta = *local;
        return true;
    }

    void cancel_native_condition_gizmo(
        std::string reason, bool release_capture = true) {
        if (!native_condition_gizmo_drag.has_value()) return;
        native_condition_gizmo_drag.reset();
        if (release_capture) release_native_capture();
        action_feedback = std::move(reason);
        action_feedback_error = true;
    }

    bool begin_native_condition_gizmo_drag(
        const carto::ui::NativePointerEvent& event,
        const UiSnapshot& snapshot,
        ImVec2 pointer) {
        if (!event.pressed || event.button != carto::ui::NativePointerButton::primary ||
            snapshot.workspace_kind != carto::ui::Workspace::condition ||
            carto::ui::selection_operation_for_native_pointer(event) !=
                std::optional<carto::editor::SelectionOperation>{
                    carto::editor::SelectionOperation::replace}) {
            return false;
        }
        constexpr float kHandleRadiusSquared = 12.0F * 12.0F;
        const NativeConditionGizmoHandle* hit = nullptr;
        float best = kHandleRadiusSquared;
        for (const auto& candidate : native_viewport_hits.condition_gizmos) {
            const float dx = candidate.handle.x - pointer.x;
            const float dy = candidate.handle.y - pointer.y;
            const float distance = dx * dx + dy * dy;
            if (distance < best) {
                best = distance;
                hit = &candidate;
            }
        }
        if (hit == nullptr) return false;
        const auto authoring = session.condition_authoring();
        if (!authoring || authoring.value().project_revision != hit->authoring_revision ||
            snapshot.project_revision != native_viewport_hits.project_revision) {
            action_feedback = authoring
                ? "Acoustic gizmo input is stale; rebuild the viewport and retry."
                : authoring.error().message;
            action_feedback_error = true;
            return true;
        }
        NativeConditionGizmoDrag capture;
        capture.handle = *hit;
        capture.project_revision = snapshot.project_revision;
        capture.viewport = ImRect(native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        capture.preview_minimum = hit->minimum_distance;
        capture.preview_maximum = hit->maximum_distance;
        capture.preview_radius = hit->radius;
        capture.preview_half_extents = hit->half_extents;
        native_condition_gizmo_drag = std::move(capture);
        acquire_native_capture();
        action_feedback = "Drag the acoustic handle; release to commit a revision-bound edit.";
        action_feedback_error = false;
        return true;
    }

    bool route_native_condition_gizmo_drag(const carto::ui::NativePointerEvent& event) {
        if (!native_condition_gizmo_drag.has_value()) return false;
        const auto snapshot = ui.snapshot();
        if (snapshot.workspace_kind != carto::ui::Workspace::condition ||
            snapshot.project_revision != native_condition_gizmo_drag->project_revision) {
            cancel_native_condition_gizmo(
                "Acoustic gizmo cancelled because its project snapshot changed.");
            return true;
        }
        carto::core::Vec2d pointer;
        if (!native_pointer_viewport_position(event, pointer)) {
            cancel_native_condition_gizmo(
                "Acoustic gizmo cancelled because pointer position is unavailable.");
            return true;
        }
        if (!native_condition_gizmo_drag->viewport.Contains(ImVec2(
                static_cast<float>(pointer.x), static_cast<float>(pointer.y)))) {
            cancel_native_condition_gizmo(
                "Acoustic gizmo cancelled after the pointer left the viewport.");
            return true;
        }
        carto::core::Vec3d local_delta;
        if (!condition_gizmo_local_delta(
                native_condition_gizmo_drag->handle, pointer, local_delta)) {
            cancel_native_condition_gizmo("Acoustic gizmo could not resolve local coordinates.");
            return true;
        }
        auto& capture = *native_condition_gizmo_drag;
        const double radius = std::hypot(local_delta.x, local_delta.z);
        switch (capture.handle.kind) {
        case NativeConditionGizmoKind::audio_minimum_distance:
            capture.preview_minimum = std::clamp(radius, 0.0,
                std::max(0.0, capture.handle.maximum_distance - 0.01));
            break;
        case NativeConditionGizmoKind::audio_maximum_distance:
            capture.preview_maximum = std::clamp(radius,
                capture.handle.minimum_distance + 0.01, 1.0e6);
            break;
        case NativeConditionGizmoKind::acoustic_sphere_radius:
            capture.preview_radius = std::clamp(radius, 0.01, 1.0e6);
            break;
        case NativeConditionGizmoKind::acoustic_box_corner:
            capture.preview_half_extents = {
                std::clamp(std::abs(local_delta.x), 0.01, 1.0e6),
                capture.handle.half_extents.y,
                std::clamp(std::abs(local_delta.z), 0.01, 1.0e6)};
            break;
        }
        if (event.pressed) return true;

        const auto kind = capture.handle.kind;
        const auto record_id = capture.handle.record_id;
        const auto expected_revision = capture.handle.authoring_revision;
        const auto minimum_distance = capture.preview_minimum;
        const auto maximum_distance = capture.preview_maximum;
        const auto preview_radius = capture.preview_radius;
        const auto half_extents = capture.preview_half_extents;
        const auto initial_minimum = capture.handle.minimum_distance;
        const auto initial_maximum = capture.handle.maximum_distance;
        const auto initial_radius = capture.handle.radius;
        const auto initial_half_extents = capture.handle.half_extents;
        native_condition_gizmo_drag.reset();
        release_native_capture();

        if (kind == NativeConditionGizmoKind::audio_minimum_distance ||
            kind == NativeConditionGizmoKind::audio_maximum_distance) {
            if (minimum_distance != initial_minimum || maximum_distance != initial_maximum) {
                const auto updated = ui.update_condition_audio_source_distances(
                    record_id, expected_revision, minimum_distance, maximum_distance);
                action_feedback = updated
                    ? "Committed acoustic source distance through project command history."
                    : updated.error().message;
                action_feedback_error = !updated;
            } else {
                action_feedback = "Acoustic source distance is unchanged.";
                action_feedback_error = false;
            }
        } else if ((kind == NativeConditionGizmoKind::acoustic_sphere_radius &&
                    preview_radius != initial_radius) ||
                   (kind == NativeConditionGizmoKind::acoustic_box_corner &&
                    (half_extents.x != initial_half_extents.x ||
                     half_extents.z != initial_half_extents.z))) {
            const auto updated = ui.update_condition_acoustic_zone_volume(
                record_id, expected_revision, half_extents, preview_radius);
            action_feedback = updated
                ? "Committed acoustic-zone volume through project command history."
                : updated.error().message;
            action_feedback_error = !updated;
        } else {
            action_feedback = "Acoustic zone volume is unchanged.";
            action_feedback_error = false;
        }
        return true;
    }

    void cancel_native_transform_drag(std::string reason, bool release_capture = true) {
        if (!native_transform_drag.has_value()) return;
        native_transform_drag.reset();
        if (release_capture) release_native_capture();
        action_feedback = std::move(reason);
        action_feedback_error = true;
    }

    bool begin_native_transform_drag(
        const carto::ui::NativePointerEvent& event,
        const UiSnapshot& snapshot,
        ImVec2 screen_point) {
        const bool ghost_edit = agent_ghost_edit_mode &&
            agent_preview_mode == 2 && snapshot.agent_task.has_value() &&
            snapshot.project_revision == snapshot.agent_task->base_revision &&
            snapshot.agent_task->status != carto::agent::TaskStatus::accepted &&
            snapshot.agent_task->status != carto::agent::TaskStatus::rejected;
        if (!event.pressed || event.button != carto::ui::NativePointerButton::primary ||
            surface != ShellSurface::workspace ||
            (!ghost_edit && !carto::ui::workspace_supports_scene_object_translation(
                snapshot.workspace_kind)) ||
            (!ghost_edit && snapshot.selection.mode != carto::editor::SelectionMode::object) ||
            (!ghost_edit && snapshot.selection.objects.size() != 1U) ||
            !native_viewport_hits.translate_gizmo.has_value() ||
            native_transform_drag.has_value()) {
            return false;
        }
        const auto& gizmo = *native_viewport_hits.translate_gizmo;
        if (snapshot.project_revision != gizmo.project_revision ||
            snapshot.project_revision != native_viewport_hits.project_revision ||
            (ghost_edit && agent_ghost_selected_object != gizmo.object) ||
            (!ghost_edit && snapshot.selection.objects.front() != gizmo.object)) {
            return false;
        }
        const auto handle_start = [&gizmo](ImVec2 tip) {
            const ImVec2 delta = tip - gizmo.origin;
            const float length = std::sqrt(delta.x * delta.x + delta.y * delta.y);
            if (!std::isfinite(length) || length <= 1.0e-4F) return gizmo.origin;
            return gizmo.origin + delta * (8.0F / length);
        };
        const float x_distance = point_segment_distance_squared(
            screen_point, handle_start(gizmo.x_tip), gizmo.x_tip);
        const float z_distance = point_segment_distance_squared(
            screen_point, handle_start(gizmo.z_tip), gizmo.z_tip);
        constexpr float kHandleRadiusSquared = kTranslateGizmoHitRadius * kTranslateGizmoHitRadius;
        if (x_distance > kHandleRadiusSquared && z_distance > kHandleRadiusSquared) {
            return false;
        }
        const auto object = std::find_if(snapshot.objects.begin(), snapshot.objects.end(),
            [&gizmo](const auto& value) { return value.object.id == gizmo.object; });
        if (object == snapshot.objects.end() || object->object.locked) {
            return false;
        }
        carto::core::Transform initial_transform = object->world_transform;
        std::optional<carto::core::Transform> parent_world_transform;
        if (!ghost_edit && object->object.parent.has_value()) {
            const auto parent = std::find_if(snapshot.objects.begin(), snapshot.objects.end(),
                [&object](const auto& value) {
                    return value.object.id == *object->object.parent;
                });
            if (parent == snapshot.objects.end()) {
                action_feedback = "Transform cancelled because the selected object's parent is unavailable.";
                action_feedback_error = true;
                return true;
            }
            const auto local_check = carto::editor::viewport_local_transform_from_world(
                parent->world_transform, object->world_transform);
            if (!local_check) {
                action_feedback = local_check.error().message;
                action_feedback_error = true;
                return true;
            }
            parent_world_transform = parent->world_transform;
        }
        if (ghost_edit) {
            const auto branch_instances = snapshot.agent_task->after_scene.instances();
            const auto branch_instance = std::find_if(
                branch_instances.begin(), branch_instances.end(),
                [&gizmo](const auto& instance) { return instance.object == gizmo.object; });
            if (branch_instance == branch_instances.end() ||
                std::find(snapshot.agent_task->scope_objects.begin(),
                    snapshot.agent_task->scope_objects.end(), gizmo.object) ==
                    snapshot.agent_task->scope_objects.end() ||
                std::find(snapshot.agent_task->protected_objects.begin(),
                    snapshot.agent_task->protected_objects.end(), gizmo.object) !=
                    snapshot.agent_task->protected_objects.end()) {
                return false;
            }
            initial_transform = branch_instance->world_transform;
        }
        const auto axis = x_distance <= z_distance
            ? carto::editor::ViewportTranslateAxis::world_x
            : carto::editor::ViewportTranslateAxis::world_z;
        const carto::core::Vec2d screen_axis_per_world_unit = axis ==
                carto::editor::ViewportTranslateAxis::world_x
            ? gizmo.screen_x_axis_per_world : gizmo.screen_z_axis_per_world;
        if (ghost_edit && agent_ghost_justification.empty()) {
            action_feedback = "Enter a correction justification before editing the ghost.";
            action_feedback_error = true;
            return true;
        }
        carto::core::Vec2d pointer{
            static_cast<double>(screen_point.x), static_cast<double>(screen_point.y)};
        NativeTransformDragCapture capture;
        if (auto result = capture.session.begin_projected(gizmo.object, initial_transform,
                snapshot.project_revision, axis, pointer,
                screen_axis_per_world_unit); !result) {
            action_feedback = result.error().message;
            action_feedback_error = true;
            return true;
        }
        capture.axis = axis;
        capture.snap_perpendicular_tolerance =
            static_cast<double>(geometry_snap_alignment_tolerance);
        capture.viewport = ImRect(
            native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        capture.initial_transform = initial_transform;
        capture.preview_transform = capture.initial_transform;
        capture.parent_world_transform = parent_world_transform;
        capture.agent_ghost = ghost_edit;
        if (ghost_edit) {
            capture.agent_task_id = snapshot.agent_task->task_id;
            capture.agent_branch_revision = snapshot.agent_task->speculative_revision;
        }
        native_transform_drag = std::move(capture);
        acquire_native_capture();
        return true;
    }

    bool route_native_transform_drag(const carto::ui::NativePointerEvent& event) {
        if (!native_transform_drag.has_value()) return false;
        const auto snapshot = ui.snapshot();
        if (snapshot.project_revision != native_transform_drag->session.source_revision()) {
            cancel_native_transform_drag(
                "Transform cancelled because the project revision changed.");
            return true;
        }
        if (native_transform_drag->agent_ghost &&
            (!snapshot.agent_task.has_value() ||
             snapshot.agent_task->task_id != native_transform_drag->agent_task_id ||
             snapshot.agent_task->speculative_revision !=
                native_transform_drag->agent_branch_revision ||
             snapshot.project_revision != snapshot.agent_task->base_revision)) {
            cancel_native_transform_drag(
                "Ghost transform cancelled because the task branch changed.");
            return true;
        }
        carto::core::Vec2d pointer;
        if (!native_pointer_viewport_position(event, pointer)) {
            cancel_native_transform_drag("Transform cancelled because pointer position is unavailable.");
            return true;
        }
        if (!native_transform_drag->viewport.Contains(ImVec2(
                static_cast<float>(pointer.x), static_cast<float>(pointer.y)))) {
            cancel_native_transform_drag("Transform cancelled after the pointer left the viewport.");
            return true;
        }
        auto preview = native_transform_drag->session.preview(
            pointer, snapshot.project_revision);
        if (!preview) {
            cancel_native_transform_drag(preview.error().message);
            return true;
        }
        const bool grid_snap =
            (event.modifiers & carto::ui::kNativeModifierControl) != 0U;
        const bool geometry_snap = !grid_snap &&
            (event.modifiers & carto::ui::kNativeModifierShift) != 0U;
        const auto snapped_preview = carto::editor::snap_viewport_transform_preview(
            preview.value(), native_transform_drag->axis, snapshot.viewport.scene,
            snapshot.project_revision, grid_snap, geometry_snap,
            native_transform_drag->geometry_snap_session,
            std::optional<carto::scene::ObjectId>{
                native_transform_drag->session.object()},
            native_transform_drag->snap_perpendicular_tolerance);
        if (!snapped_preview) {
            cancel_native_transform_drag(snapped_preview.error().message);
            return true;
        }
        native_transform_drag->geometry_snap_candidate =
            snapped_preview.value().candidate;
        native_transform_drag->preview_transform = snapped_preview.value().transform;
        if (event.pressed) {
            if (grid_snap) {
                action_feedback = "Translate preview · 0.25 m grid snap";
            } else if (geometry_snap &&
                native_transform_drag->geometry_snap_candidate.has_value()) {
                const auto& candidate =
                    *native_transform_drag->geometry_snap_candidate;
                const char* kind = candidate.kind == carto::editor::SnapKind::vertex
                    ? "vertex" : candidate.kind == carto::editor::SnapKind::edge_midpoint
                        ? "edge midpoint" : "face center";
                action_feedback = std::string("Translate preview · snapped to ") +
                    kind + " on object " + std::to_string(candidate.object->value);
            } else if (geometry_snap) {
                action_feedback = "Translate preview · no aligned geometry target within 0.25 m";
            } else {
                action_feedback = "Translate preview · X/Z axis constrained";
            }
            action_feedback_error = false;
            return true;
        }

        const auto object = native_transform_drag->session.object();
        const auto source_revision = native_transform_drag->session.source_revision();
        const auto initial = native_transform_drag->initial_transform;
        auto capture = std::move(*native_transform_drag);
        const auto committed_transform = capture.session.complete(
            pointer, snapshot.project_revision);
        native_transform_drag.reset();
        release_native_capture();
        if (!committed_transform) {
            action_feedback = committed_transform.error().message;
            action_feedback_error = true;
            return true;
        }
        const auto final_preview = carto::editor::snap_viewport_transform_preview(
            committed_transform.value(), capture.axis, snapshot.viewport.scene,
            snapshot.project_revision, grid_snap, geometry_snap,
            capture.geometry_snap_session, std::optional<carto::scene::ObjectId>{object},
            capture.snap_perpendicular_tolerance);
        if (!final_preview) {
            action_feedback = final_preview.error().message;
            action_feedback_error = true;
            return true;
        }
        auto final_transform = final_preview.value().transform;
        if (final_preview.value().candidate.has_value()) {
            const auto& candidate = *final_preview.value().candidate;
            const auto* target = candidate.object.has_value()
                ? snapshot.viewport.scene.find(*candidate.object) : nullptr;
            if (candidate.source_revision != source_revision ||
                !candidate.object.has_value() || !candidate.mesh_asset.has_value() ||
                target == nullptr || target->mesh == nullptr ||
                target->mesh_asset != candidate.mesh_asset ||
                target->mesh->source_revision != candidate.mesh_revision) {
                action_feedback =
                    "Transform cancelled because its geometry snap receipt is stale or incomplete.";
                action_feedback_error = true;
                return true;
            }
        }
        const bool changed = capture.axis == carto::editor::ViewportTranslateAxis::world_x
            ? final_transform.translation.x != initial.translation.x
            : final_transform.translation.z != initial.translation.z;
        if (changed) {
            if (capture.agent_ghost) {
                const auto corrected = ui.correct_agent_ghost_transform(
                    object, final_transform, agent_ghost_justification);
                if (corrected) {
                    agent_ghost_justification.clear();
                    action_feedback = "Human correction locked into the speculative branch; gates rechecked.";
                    action_feedback_error = false;
                } else {
                    action_feedback = corrected.error().message;
                    action_feedback_error = true;
                }
            } else {
                if (capture.parent_world_transform.has_value()) {
                    const auto local_transform =
                        carto::editor::viewport_local_transform_from_world(
                            *capture.parent_world_transform, final_transform);
                    if (!local_transform) {
                        action_feedback = local_transform.error().message;
                        action_feedback_error = true;
                        return true;
                    }
                    final_transform = local_transform.value();
                }
                static_cast<void>(dispatch(SetObjectTransformAction{
                    object, final_transform, source_revision}));
            }
        }
        return true;
    }

    void cancel_native_sculpt_stroke(std::string reason, bool release_capture = true) {
        if (!native_sculpt_stroke.has_value()) return;
        native_sculpt_stroke.reset();
        if (release_capture) release_native_capture();
        action_feedback = std::move(reason);
        action_feedback_error = true;
    }

    bool begin_native_sculpt_stroke(const carto::ui::NativePointerEvent& event) {
        if (!event.pressed || event.button != carto::ui::NativePointerButton::primary ||
            surface != ShellSurface::workspace || !native_viewport_hits.valid ||
            !native_viewport_hits.interactive ||
            carto::ui::selection_operation_for_native_pointer(event) !=
                std::optional<carto::editor::SelectionOperation>{
                    carto::editor::SelectionOperation::replace}) {
            return false;
        }
        const auto snapshot = ui.snapshot();
        if (snapshot.workspace_kind != carto::ui::Workspace::sculpt ||
            snapshot.project_generation != native_viewport_hits.project_generation ||
            snapshot.project_revision != native_viewport_hits.project_revision) {
            return false;
        }
        std::optional<carto::scene::ObjectId> target;
        if (snapshot.selection.component_object.has_value()) {
            target = snapshot.selection.component_object;
        } else if (snapshot.selection.objects.size() == 1U) {
            target = snapshot.selection.objects.front();
        }
        if (!target.has_value()) return false;
        const auto object = std::find_if(
            snapshot.objects.begin(), snapshot.objects.end(), [target](const auto& value) {
                return value.object.id == *target;
            });
        if (object == snapshot.objects.end() || !object->object.mesh_asset.has_value() ||
            object->object.locked || !object->object.visible) {
            return false;
        }

        carto::core::Vec2d screen_position;
        if (!native_pointer_viewport_position(event, screen_position)) return false;
        const ImVec2 point{
            static_cast<float>(screen_position.x), static_cast<float>(screen_position.y)};
        const ImRect viewport(
            native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        if (!viewport.Contains(point)) return false;
        if (native_viewport_hits.sculpt_triangles_truncated) {
            action_feedback = "This selected mesh exceeds the viewport stroke sampling bound.";
            action_feedback_error = true;
            return true;
        }
        std::string surface_diagnostic;
        if (!viewport_surface_frontmost_at(screen_position, *target,
                snapshot.project_generation, snapshot.project_revision,
                viewport, surface_diagnostic)) {
            action_feedback = std::move(surface_diagnostic);
            action_feedback_error = true;
            return true;
        }

        NativeSculptStrokeCapture capture;
        capture.project_revision = snapshot.project_revision;
        capture.project_generation = snapshot.project_generation;
        capture.perspective_camera = perspective_camera_active;
        capture.perspective_camera_state = perspective_camera;
        capture.work_surface_camera_state = work_surface_camera;
        capture.object = *target;
        capture.mesh_asset = *object->object.mesh_asset;
        capture.mode = static_cast<carto::production::SculptStrokeMode>(
            std::clamp(sculpt_mode_index, 0, 11));
        capture.radius = sculpt_radius;
        capture.strength = sculpt_strength;
        capture.viewport = viewport;
        capture.screen_path.reserve(128U);
        capture.screen_path.push_back(screen_position);
        for (const auto& triangle : native_viewport_hits.sculpt_triangles) {
            if (triangle.object == *target) capture.triangles.push_back(triangle);
        }
        if (capture.triangles.empty()) return false;
        const auto initial_hit = carto::ui::sample_sculpt_viewport_surface(
            capture.triangles, capture.object, screen_position);
        if (!initial_hit) return false;
        if (!std::isfinite(capture.radius) || capture.radius <= 0.0 ||
            !std::isfinite(capture.strength) || capture.strength <= 0.0) {
            action_feedback = "Sculpt radius and strength must be finite and positive.";
            action_feedback_error = true;
            return true;
        }
        native_sculpt_stroke = std::move(capture);
        acquire_native_capture();
        if (!owns_native_capture()) {
            native_sculpt_stroke.reset();
            action_feedback = "The desktop could not capture the sculpt pointer.";
            action_feedback_error = true;
            return true;
        }
        return true;
    }

    bool continue_native_sculpt_stroke(const carto::ui::NativePointerEvent& event) {
        if (!native_sculpt_stroke.has_value()) return false;
        carto::core::Vec2d position;
        if (!native_pointer_viewport_position(event, position)) {
            cancel_native_sculpt_stroke("Sculpt stroke cancelled because the cursor position was unavailable.");
            return true;
        }
        const auto snapshot = ui.snapshot();
        if (snapshot.project_generation != native_sculpt_stroke->project_generation ||
            snapshot.project_revision != native_sculpt_stroke->project_revision ||
            !viewport_camera_matches(native_sculpt_stroke->perspective_camera,
                native_sculpt_stroke->perspective_camera_state,
                native_sculpt_stroke->work_surface_camera_state) ||
            snapshot.workspace_kind != carto::ui::Workspace::sculpt) {
            cancel_native_sculpt_stroke(
                "Sculpt stroke cancelled because its project snapshot or "
                "viewport camera changed.");
            return true;
        }
        const ImVec2 point{static_cast<float>(position.x), static_cast<float>(position.y)};
        if (!native_sculpt_stroke->viewport.Contains(point)) {
            cancel_native_sculpt_stroke("Sculpt stroke cancelled when the cursor left the viewport.");
            return true;
        }
        std::string surface_diagnostic;
        if (!viewport_surface_frontmost_at(position, native_sculpt_stroke->object,
                native_sculpt_stroke->project_generation,
                native_sculpt_stroke->project_revision,
                native_sculpt_stroke->viewport, surface_diagnostic)) {
            cancel_native_sculpt_stroke(std::move(surface_diagnostic));
            return true;
        }
        if (native_sculpt_stroke->screen_path.size() >= kMaxNativeSculptCursorPoints) {
            cancel_native_sculpt_stroke("Sculpt stroke exceeded its bounded cursor path.");
            return true;
        }
        const auto& last = native_sculpt_stroke->screen_path.back();
        if (position.x != last.x || position.y != last.y) {
            std::string segment_diagnostic;
            if (!viewport_surface_segment_frontmost(last, position,
                    native_sculpt_stroke->object,
                    native_sculpt_stroke->project_generation,
                    native_sculpt_stroke->project_revision,
                    native_sculpt_stroke->viewport, segment_diagnostic)) {
                cancel_native_sculpt_stroke(std::move(segment_diagnostic));
                return true;
            }
            native_sculpt_stroke->screen_path.push_back(position);
        }
        return true;
    }

    bool finish_native_sculpt_stroke(const carto::ui::NativePointerEvent& event) {
        if (!native_sculpt_stroke.has_value()) return false;
        if (!viewport_camera_matches(native_sculpt_stroke->perspective_camera,
                native_sculpt_stroke->perspective_camera_state,
                native_sculpt_stroke->work_surface_camera_state)) {
            cancel_native_sculpt_stroke(
                "Sculpt stroke cancelled because the viewport camera changed.");
            return true;
        }
        carto::core::Vec2d position;
        if (!native_pointer_viewport_position(event, position)) {
            cancel_native_sculpt_stroke("Sculpt stroke cancelled because the cursor position was unavailable.");
            return true;
        }
        const ImVec2 point{static_cast<float>(position.x), static_cast<float>(position.y)};
        if (!native_sculpt_stroke->viewport.Contains(point)) {
            cancel_native_sculpt_stroke("Sculpt stroke cancelled when the cursor left the viewport.");
            return true;
        }
        std::string surface_diagnostic;
        if (!viewport_surface_frontmost_at(position, native_sculpt_stroke->object,
                native_sculpt_stroke->project_generation,
                native_sculpt_stroke->project_revision,
                native_sculpt_stroke->viewport, surface_diagnostic)) {
            cancel_native_sculpt_stroke(std::move(surface_diagnostic));
            return true;
        }
        if (native_sculpt_stroke->screen_path.size() >= kMaxNativeSculptCursorPoints) {
            cancel_native_sculpt_stroke("Sculpt stroke exceeded its bounded cursor path.");
            return true;
        }
        const auto& last = native_sculpt_stroke->screen_path.back();
        if (position.x != last.x || position.y != last.y) {
            std::string segment_diagnostic;
            if (!viewport_surface_segment_frontmost(last, position,
                    native_sculpt_stroke->object,
                    native_sculpt_stroke->project_generation,
                    native_sculpt_stroke->project_revision,
                    native_sculpt_stroke->viewport, segment_diagnostic)) {
                cancel_native_sculpt_stroke(std::move(segment_diagnostic));
                return true;
            }
            native_sculpt_stroke->screen_path.push_back(position);
        }
        NativeSculptStrokeCapture capture = std::move(*native_sculpt_stroke);
        native_sculpt_stroke.reset();
        release_native_capture();

        const auto snapshot = ui.snapshot();
        const auto selected = snapshot.selection.component_object.has_value()
            ? snapshot.selection.component_object
            : (snapshot.selection.objects.size() == 1U
                ? std::optional<carto::scene::ObjectId>{snapshot.selection.objects.front()}
                : std::nullopt);
        if (snapshot.project_generation != capture.project_generation ||
            snapshot.project_revision != capture.project_revision ||
            !viewport_camera_matches(capture.perspective_camera,
                capture.perspective_camera_state, capture.work_surface_camera_state) ||
            snapshot.workspace_kind != carto::ui::Workspace::sculpt ||
            selected != std::optional<carto::scene::ObjectId>{capture.object}) {
            action_feedback = "Sculpt stroke cancelled because its selected source changed.";
            action_feedback_error = true;
            return true;
        }
        auto samples = carto::ui::sample_sculpt_viewport_stroke(
            capture.triangles, capture.object, capture.screen_path, 4.0);
        if (!samples) {
            action_feedback = samples.error().message;
            action_feedback_error = true;
            return true;
        }
        static_cast<void>(dispatch(carto::application::AppendSculptSurfaceStrokeAction{
            capture.project_revision,
            capture.object,
            capture.mesh_asset,
            capture.mode,
            capture.radius,
            capture.strength,
            std::move(samples.value()),
            capture.project_generation}));
        return true;
    }

    void cancel_native_knife_stroke(std::string reason, bool release_capture = true) {
        if (!native_knife_stroke.has_value()) return;
        native_knife_stroke.reset();
        if (release_capture) release_native_capture();
        action_feedback = std::move(reason);
        action_feedback_error = true;
    }

    bool begin_native_knife_stroke(const carto::ui::NativePointerEvent& event) {
        if (!mesh_knife_mode_active || !event.pressed ||
            event.button != carto::ui::NativePointerButton::primary ||
            surface != ShellSurface::workspace || !native_viewport_hits.valid ||
            !native_viewport_hits.interactive ||
            carto::ui::selection_operation_for_native_pointer(event) !=
                std::optional<carto::editor::SelectionOperation>{
                    carto::editor::SelectionOperation::replace}) {
            return false;
        }
        const auto snapshot = ui.snapshot();
        if (snapshot.workspace_kind != carto::ui::Workspace::model ||
            snapshot.project_generation != native_viewport_hits.project_generation ||
            snapshot.project_revision != native_viewport_hits.project_revision ||
            snapshot.selection.mode != carto::editor::SelectionMode::face) {
            return false;
        }
        const auto groups = snapshot.selection.component_groups;
        if (groups.size() != 1U || groups.front().faces.size() != 1U) return false;
        const auto object = std::find_if(snapshot.objects.begin(), snapshot.objects.end(),
            [&](const auto& candidate) { return candidate.object.id == groups.front().object; });
        if (object == snapshot.objects.end() || !object->object.mesh_asset.has_value() ||
            object->object.locked || !object->object.visible) {
            action_feedback = "Knife cut requires a visible, unlocked selected mesh.";
            action_feedback_error = true;
            return true;
        }
        if (native_viewport_hits.sculpt_triangles_truncated) {
            action_feedback = "This face exceeds the viewport knife-sampling bound.";
            action_feedback_error = true;
            return true;
        }

        carto::core::Vec2d screen_position;
        if (!native_pointer_viewport_position(event, screen_position)) return false;
        const ImVec2 pointer{static_cast<float>(screen_position.x),
            static_cast<float>(screen_position.y)};
        const ImRect viewport(native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        if (!viewport.Contains(pointer)) return false;
        std::string surface_diagnostic;
        if (!viewport_surface_frontmost_at(screen_position, groups.front().object,
                snapshot.project_generation, snapshot.project_revision,
                viewport, surface_diagnostic)) {
            action_feedback = std::move(surface_diagnostic);
            action_feedback_error = true;
            return true;
        }

        NativeKnifeStrokeCapture capture;
        capture.project_revision = snapshot.project_revision;
        capture.project_generation = snapshot.project_generation;
        capture.perspective_camera = perspective_camera_active;
        capture.perspective_camera_state = perspective_camera;
        capture.work_surface_camera_state = work_surface_camera;
        capture.object = groups.front().object;
        capture.mesh_asset = *object->object.mesh_asset;
        capture.face = groups.front().faces.front();
        capture.viewport = viewport;
        for (const auto& triangle : native_viewport_hits.sculpt_triangles) {
            if (triangle.object == capture.object && triangle.face == capture.face) {
                capture.triangles.push_back(triangle);
            }
        }
        if (capture.triangles.empty()) {
            action_feedback = "The selected face is not present in the current viewport snapshot.";
            action_feedback_error = true;
            return true;
        }
        const auto start_sample = carto::ui::sample_sculpt_viewport_surface(
            capture.triangles, capture.object, screen_position);
        if (!start_sample) {
            action_feedback = start_sample.error().message;
            action_feedback_error = true;
            return true;
        }
        capture.screen_path.reserve(128U);
        capture.screen_path.push_back(screen_position);
        native_knife_stroke = std::move(capture);
        acquire_native_capture();
        if (!owns_native_capture()) {
            native_knife_stroke.reset();
            action_feedback = "The desktop could not capture the knife pointer.";
            action_feedback_error = true;
            return true;
        }
        return true;
    }

    bool continue_native_knife_stroke(const carto::ui::NativePointerEvent& event) {
        if (!native_knife_stroke.has_value()) return false;
        carto::core::Vec2d position;
        if (!native_pointer_viewport_position(event, position)) {
            cancel_native_knife_stroke("Knife cut cancelled because the cursor position was unavailable.");
            return true;
        }
        const auto snapshot = ui.snapshot();
        const auto groups = snapshot.selection.component_groups;
        if (snapshot.project_generation != native_knife_stroke->project_generation ||
            snapshot.project_revision != native_knife_stroke->project_revision ||
            !viewport_camera_matches(native_knife_stroke->perspective_camera,
                native_knife_stroke->perspective_camera_state,
                native_knife_stroke->work_surface_camera_state) ||
            !mesh_knife_mode_active ||
            snapshot.workspace_kind != carto::ui::Workspace::model ||
            snapshot.selection.mode != carto::editor::SelectionMode::face ||
            groups.size() != 1U || groups.front().object != native_knife_stroke->object ||
            groups.front().faces.size() != 1U ||
            groups.front().faces.front() != native_knife_stroke->face) {
            cancel_native_knife_stroke(
                "Knife cut cancelled because its project, viewport camera, or "
                "selected face changed.");
            return true;
        }
        const ImVec2 pointer{static_cast<float>(position.x), static_cast<float>(position.y)};
        if (!native_knife_stroke->viewport.Contains(pointer)) {
            cancel_native_knife_stroke("Knife cut cancelled when the cursor left the viewport.");
            return true;
        }
        std::string surface_diagnostic;
        if (!viewport_surface_frontmost_at(position, native_knife_stroke->object,
                native_knife_stroke->project_generation,
                native_knife_stroke->project_revision,
                native_knife_stroke->viewport, surface_diagnostic)) {
            cancel_native_knife_stroke(std::move(surface_diagnostic));
            return true;
        }
        if (native_knife_stroke->screen_path.size() >= kMaxNativeKnifeCursorPoints) {
            cancel_native_knife_stroke("Knife cut exceeded its bounded cursor path.");
            return true;
        }
        const auto& last = native_knife_stroke->screen_path.back();
        if (position.x != last.x || position.y != last.y) {
            std::string segment_diagnostic;
            if (!viewport_surface_segment_frontmost(last, position,
                    native_knife_stroke->object,
                    native_knife_stroke->project_generation,
                    native_knife_stroke->project_revision,
                    native_knife_stroke->viewport, segment_diagnostic)) {
                cancel_native_knife_stroke(std::move(segment_diagnostic));
                return true;
            }
            native_knife_stroke->screen_path.push_back(position);
        }
        return true;
    }

    bool finish_native_knife_stroke(const carto::ui::NativePointerEvent& event) {
        if (!native_knife_stroke.has_value()) return false;
        if (!viewport_camera_matches(native_knife_stroke->perspective_camera,
                native_knife_stroke->perspective_camera_state,
                native_knife_stroke->work_surface_camera_state)) {
            cancel_native_knife_stroke(
                "Knife cut cancelled because the viewport camera changed.");
            return true;
        }
        carto::core::Vec2d position;
        if (!native_pointer_viewport_position(event, position)) {
            cancel_native_knife_stroke("Knife cut cancelled because the cursor position was unavailable.");
            return true;
        }
        const ImVec2 pointer{static_cast<float>(position.x), static_cast<float>(position.y)};
        if (!native_knife_stroke->viewport.Contains(pointer)) {
            cancel_native_knife_stroke("Knife cut cancelled when the cursor left the viewport.");
            return true;
        }
        std::string surface_diagnostic;
        if (!viewport_surface_frontmost_at(position, native_knife_stroke->object,
                native_knife_stroke->project_generation,
                native_knife_stroke->project_revision,
                native_knife_stroke->viewport, surface_diagnostic)) {
            cancel_native_knife_stroke(std::move(surface_diagnostic));
            return true;
        }
        if (native_knife_stroke->screen_path.size() >= kMaxNativeKnifeCursorPoints) {
            cancel_native_knife_stroke("Knife cut exceeded its bounded cursor path.");
            return true;
        }
        const auto& last = native_knife_stroke->screen_path.back();
        if (position.x != last.x || position.y != last.y) {
            std::string segment_diagnostic;
            if (!viewport_surface_segment_frontmost(last, position,
                    native_knife_stroke->object,
                    native_knife_stroke->project_generation,
                    native_knife_stroke->project_revision,
                    native_knife_stroke->viewport, segment_diagnostic)) {
                cancel_native_knife_stroke(std::move(segment_diagnostic));
                return true;
            }
            native_knife_stroke->screen_path.push_back(position);
        }
        NativeKnifeStrokeCapture capture = std::move(*native_knife_stroke);
        native_knife_stroke.reset();
        release_native_capture();

        const auto snapshot = ui.snapshot();
        const auto groups = snapshot.selection.component_groups;
        if (snapshot.project_generation != capture.project_generation ||
            snapshot.project_revision != capture.project_revision ||
            !viewport_camera_matches(capture.perspective_camera,
                capture.perspective_camera_state, capture.work_surface_camera_state) ||
            !mesh_knife_mode_active ||
            snapshot.workspace_kind != carto::ui::Workspace::model ||
            snapshot.selection.mode != carto::editor::SelectionMode::face ||
            groups.size() != 1U || groups.front().object != capture.object ||
            groups.front().faces.size() != 1U || groups.front().faces.front() != capture.face) {
            action_feedback = "Knife cut cancelled because its selected face changed.";
            action_feedback_error = true;
            return true;
        }
        auto path = carto::ui::sample_knife_viewport_stroke(
            capture.triangles, capture.object, capture.face, capture.screen_path);
        if (!path) {
            action_feedback = path.error().message;
            action_feedback_error = true;
            return true;
        }
        carto::editor::ToolArguments arguments;
        arguments.knife_path = std::move(path.value());
        static_cast<void>(dispatch(carto::application::InvokeToolAction{
            "mesh.knife-cut", std::move(arguments)}));
        return true;
    }

    bool pointer_over_workbench_instrument(
        const carto::ui::NativePointerEvent& event) {
        if (window == nullptr || surface != ShellSurface::workspace) return false;
        // Use the last rendered ImGui window bounds, not persisted geometry.
        // A press can arrive between frames while an instrument is moving or
        // being resized; stale preferences must not let viewport hit-testing
        // consume a click intended for the instrument above it.
        const carto::core::Vec2d pointer{
            static_cast<double>(event.x), static_cast<double>(event.y)};
        for (std::size_t index = 0U;
             index < carto::ui::kWorkbenchInstrumentCount; ++index) {
            const auto instrument = static_cast<carto::ui::WorkbenchInstrument>(index);
            const ImGuiWindow* live_window = workbench.windows[index];
            if (live_window == nullptr) continue;
            const ImVec2 minimum = live_window->Pos;
            const ImVec2 maximum = live_window->Pos + live_window->Size;
            if (carto::ui::workbench_instrument_window_contains(
                    pointer, {minimum.x, minimum.y}, {maximum.x, maximum.y},
                    workbench_visible(workbench, instrument))) {
                return true;
            }
        }
        return false;
    }

    bool begin_native_workbench_instrument_drag(
        const carto::ui::NativePointerEvent& event) {
        if (!event.pressed || event.button != carto::ui::NativePointerButton::primary ||
            surface != ShellSurface::workspace || workbench.placement_mode.has_value() ||
            workbench.native_drag.has_value() || native_transform_drag.has_value() ||
            native_condition_gizmo_drag.has_value() || native_sculpt_stroke.has_value() ||
            native_knife_stroke.has_value()) {
            return false;
        }
        const auto instrument = carto::ui::topmost_workbench_drag_target(
            {static_cast<double>(event.x), static_cast<double>(event.y)},
            workbench.drag_targets);
        if (!instrument.has_value()) return false;
        const std::size_t index = workbench_index(*instrument);
        if (!workbench.window_position_valid[index]) return false;
        const ImVec2 origin = workbench.window_origins[index];
        workbench.native_drag = NativeWorkbenchInstrumentDrag{
            *instrument,
            {static_cast<double>(event.x), static_cast<double>(event.y)},
            {static_cast<double>(origin.x), static_cast<double>(origin.y)},
            false};
        if (!owns_native_capture()) acquire_native_capture();
        return true;
    }

    bool begin_work_surface_camera_pan(
        const carto::ui::NativePointerEvent& event,
        bool space_down,
        bool alt_down) {
        if (!event.pressed || surface != ShellSurface::workspace ||
            workbench.placement_mode.has_value() || workbench.native_drag.has_value() ||
            native_transform_drag.has_value() || native_condition_gizmo_drag.has_value() ||
            native_sculpt_stroke.has_value() || native_knife_stroke.has_value() ||
            mesh_knife_mode_active ||
            pointer_over_workbench_instrument(event)) {
            return false;
        }
        const ImVec2 pointer(static_cast<float>(event.x), static_cast<float>(event.y));
        const ImRect viewport(native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        // `interactive` gates scene selection and is false in Pan View / Space-pan
        // mode by design. Camera navigation must use its own eligibility instead.
        if (!carto::ui::work_surface_camera_pan_allowed(
                native_viewport_hits.valid,
                work_surface_camera_input_allowed,
                viewport.Contains(pointer))) {
            return false;
        }

        const bool request_orbit = perspective_camera_active &&
            perspective_camera_orbit_tool_active &&
            event.button == carto::ui::NativePointerButton::primary;
        bool empty_surface = false;
        if (event.button == carto::ui::NativePointerButton::primary) {
            const auto snapshot = ui.snapshot();
            const bool hit_cache_matches_revision =
                native_viewport_hits.project_generation == snapshot.project_generation &&
                native_viewport_hits.project_revision == snapshot.project_revision;
            empty_surface = carto::ui::work_surface_pointer_is_unclaimed(
                hit_cache_matches_revision, work_surface_pointer_hits_scene(pointer));
        }
        if (!request_orbit && !carto::ui::work_surface_pointer_requests_pan(
                event.button, work_surface_pan_tool_active, space_down, alt_down,
                empty_surface)) {
            return false;
        }

        work_surface_camera_panning = true;
        work_surface_camera_orbiting = request_orbit;
        work_surface_camera_pan_button = event.button ==
            carto::ui::NativePointerButton::middle ? ImGuiMouseButton_Middle
            : event.button == carto::ui::NativePointerButton::secondary
                ? ImGuiMouseButton_Right : ImGuiMouseButton_Left;
        work_surface_camera_pan_viewport_height = native_viewport_hits.extent.y;
        work_surface_camera_last_pointer = pointer;
        if (event.button == carto::ui::NativePointerButton::middle) {
            work_surface_pan_tool_active = false;
        }
        if (!owns_native_capture()) acquire_native_capture();
        return true;
    }

    [[nodiscard]] bool work_surface_pointer_hits_scene(ImVec2 pointer) const noexcept {
        const bool object_hit = std::any_of(
            native_viewport_hits.objects.begin(), native_viewport_hits.objects.end(),
            [pointer](const auto& candidate) {
                return candidate.second.Contains(pointer);
            });
        bool transform_handle_hit = false;
        if (native_viewport_hits.translate_gizmo.has_value()) {
            const auto& gizmo = *native_viewport_hits.translate_gizmo;
            constexpr float kHandleRadiusSquared = kTranslateGizmoHitRadius * kTranslateGizmoHitRadius;
            const auto handle_start = [&gizmo](ImVec2 tip) {
                const ImVec2 delta = tip - gizmo.origin;
                const float length = std::sqrt(delta.x * delta.x + delta.y * delta.y);
                if (!std::isfinite(length) || length <= 1.0e-4F) return gizmo.origin;
                return gizmo.origin + delta * (8.0F / length);
            };
            transform_handle_hit = point_segment_distance_squared(
                    pointer, handle_start(gizmo.x_tip), gizmo.x_tip) <=
                kHandleRadiusSquared ||
                point_segment_distance_squared(
                    pointer, handle_start(gizmo.z_tip), gizmo.z_tip) <=
                kHandleRadiusSquared;
        }
        const bool condition_handle_hit = std::any_of(
            native_viewport_hits.condition_gizmos.begin(),
            native_viewport_hits.condition_gizmos.end(),
            [pointer](const NativeConditionGizmoHandle& handle) {
                const float dx = handle.handle.x - pointer.x;
                const float dy = handle.handle.y - pointer.y;
                return dx * dx + dy * dy <= 12.0F * 12.0F;
            });
        return object_hit || transform_handle_hit || condition_handle_hit;
    }

    void update_workbench_instrument_drag(carto::core::Vec2d pointer) {
        if (!workbench.native_drag.has_value() || !pointer.finite()) return;
        auto& capture = *workbench.native_drag;
        if (!carto::ui::workbench_drag_threshold_crossed(
                capture.pointer_origin, pointer, 3.0)) {
            return;
        }
        const std::size_t index = workbench_index(capture.instrument);
        auto& layout = workbench.persisted.instruments[index];
        if (!capture.moved) {
            capture.moved = true;
            workbench.moving_instrument = capture.instrument;
            mark_custom_workbench();
        }
        const auto desired = carto::ui::workbench_dragged_position(
            capture.window_origin, capture.pointer_origin, pointer);
        const ImVec2 size(static_cast<float>(layout.width),
                          static_cast<float>(layout.height));
        const ImVec2 position = clamp_instrument_position(
            ImVec2(static_cast<float>(desired.x), static_cast<float>(desired.y)), size);
        layout.positioned = true;
        layout.x = static_cast<std::int32_t>(std::lround(
            position.x - workbench_viewport_work_origin.x));
        layout.y = static_cast<std::int32_t>(std::lround(
            position.y - workbench_viewport_work_origin.y));
        workbench.drag_position_pending[index] = true;
    }

    void update_work_surface_camera_pan(carto::core::Vec2d pointer) {
        if (!work_surface_camera_panning || !pointer.finite() ||
            !std::isfinite(work_surface_camera_pan_viewport_height) ||
            work_surface_camera_pan_viewport_height <= 0.0F) {
            return;
        }
        const carto::core::Vec2d delta{
            pointer.x - static_cast<double>(work_surface_camera_last_pointer.x),
            pointer.y - static_cast<double>(work_surface_camera_last_pointer.y)};
        const bool moved = work_surface_camera_orbiting
            ? perspective_camera.orbit(delta.x, delta.y)
            : (perspective_camera_active
                ? perspective_camera.pan(delta.x, delta.y,
                    work_surface_camera_pan_viewport_height)
                : work_surface_camera.pan_pixels(
                    delta, work_surface_camera_pan_viewport_height));
        if (moved) {
            if (perspective_camera_active) perspective_camera_framed = true;
            else work_surface_camera_framed = true;
            work_surface_camera_last_pointer = ImVec2(
                static_cast<float>(pointer.x), static_cast<float>(pointer.y));
        }
    }

    void finish_work_surface_camera_pan() noexcept {
        work_surface_camera_panning = false;
        work_surface_camera_orbiting = false;
        work_surface_camera_pan_button = ImGuiMouseButton_Middle;
        work_surface_camera_pan_viewport_height = 0.0F;
        release_native_capture();
    }

    void finish_native_workbench_instrument_drag() {
        if (!workbench.native_drag.has_value()) return;
        const auto capture = *workbench.native_drag;
        if (capture.moved) {
            pending_instrument_snap = capture.instrument;
            workbench.drag_position_pending[workbench_index(capture.instrument)] = true;
        }
        workbench.native_drag.reset();
        release_native_capture();
    }

    void cancel_native_workbench_instrument_drag() {
        if (!workbench.native_drag.has_value()) return;
        const auto capture = *workbench.native_drag;
        if (capture.moved) {
            pending_instrument_snap = capture.instrument;
            workbench.drag_position_pending[workbench_index(capture.instrument)] = true;
        }
        workbench.native_drag.reset();
        workbench.moving_instrument.reset();
        release_native_capture();
    }

    // Pointer capture follows the OS window that owns the active viewport, so
    // a viewport torn out to another monitor keeps its drag gestures.
    [[nodiscard]] HWND pointer_window() const noexcept {
        return native_event_window != nullptr ? native_event_window : window;
    }
    void acquire_native_capture() noexcept {
        native_capture_window = pointer_window();
        if (native_capture_window != nullptr) SetCapture(native_capture_window);
    }
    [[nodiscard]] bool owns_native_capture() const noexcept {
        return native_capture_window != nullptr && GetCapture() == native_capture_window;
    }
    void release_native_capture() noexcept {
        if (owns_native_capture()) ReleaseCapture();
        native_capture_window = nullptr;
    }

    void cancel_gestures_after_native_capture_loss() {
        using CaptureState = carto::studio::DockingWorkspace::NativeCaptureState;
        if (carto::studio::DockingWorkspace::classify_native_capture(
                native_capture_window != nullptr, owns_native_capture()) !=
            CaptureState::lost) {
            return;
        }
        if (native_knife_stroke.has_value()) {
            cancel_native_knife_stroke("Knife cut cancelled: pointer capture lost.", false);
        }
        if (native_sculpt_stroke.has_value()) {
            cancel_native_sculpt_stroke("Sculpt stroke cancelled: pointer capture lost.", false);
        }
        if (native_transform_drag.has_value()) {
            cancel_native_transform_drag("Transform cancelled: pointer capture lost.", false);
        }
        if (native_condition_gizmo_drag.has_value()) {
            cancel_native_condition_gizmo("Gizmo cancelled: pointer capture lost.", false);
        }
        if (workbench.native_drag.has_value()) {
            cancel_native_workbench_instrument_drag();
        }
        if (work_surface_camera_panning) finish_work_surface_camera_pan();
        native_capture_window = nullptr;
    }

    bool route_native_loop_cut_seed_pick(
        const carto::ui::NativePointerEvent& event) {
        const auto keep_pick_active_with_error = [this](std::string message) {
            action_feedback = std::move(message);
            action_feedback_error = true;
            return true;
        };
        const auto cancel_pick_with_error = [this](std::string message) {
            mesh_loop_cut_seed_pick_active = false;
            action_feedback = std::move(message);
            action_feedback_error = true;
            return true;
        };
        const auto snapshot = ui.snapshot();
        const auto operation =
            carto::ui::selection_operation_for_native_pointer(event);
        const ImVec2 point{static_cast<float>(event.x), static_cast<float>(event.y)};
        const ImRect viewport(
            native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        const bool current_snapshot =
            snapshot.project_generation == native_viewport_hits.project_generation &&
            snapshot.project_revision == native_viewport_hits.project_revision;
        const bool speculative_preview = agent_ghost_edit_mode &&
            agent_preview_mode == 2 && snapshot.agent_task.has_value() &&
            snapshot.project_revision == snapshot.agent_task->base_revision;
        const auto context = carto::studio::decide_loop_cut_pick_context({
            event.button == carto::ui::NativePointerButton::primary && event.pressed,
            surface == ShellSurface::workspace,
            snapshot.workspace_kind == carto::ui::Workspace::model,
            snapshot.selection.mode == carto::editor::SelectionMode::edge,
            native_viewport_hits.valid && native_viewport_hits.interactive,
            current_snapshot,
            speculative_preview,
            operation.has_value() &&
                *operation == carto::editor::SelectionOperation::replace,
            viewport.Contains(point),
        });
        if (context.disposition == carto::studio::LoopCutPickDisposition::ignore) {
            return false;
        }
        if (context.disposition == carto::studio::LoopCutPickDisposition::cancel) {
            return cancel_pick_with_error(std::string(context.message));
        }
        if (context.disposition == carto::studio::LoopCutPickDisposition::keep_armed) {
            return keep_pick_active_with_error(std::string(context.message));
        }

        const auto pick = carto::ui::resolve_projected_edge_pick(
            native_viewport_hits.edges,
            {static_cast<double>(point.x), static_cast<double>(point.y)});
        const auto pick_status = [&pick] {
            switch (pick.status) {
            case carto::ui::ProjectedEdgePickStatus::miss:
                return carto::studio::LoopCutEdgePickStatus::miss;
            case carto::ui::ProjectedEdgePickStatus::ambiguous:
                return carto::studio::LoopCutEdgePickStatus::ambiguous;
            case carto::ui::ProjectedEdgePickStatus::hit:
                return carto::studio::LoopCutEdgePickStatus::hit;
            case carto::ui::ProjectedEdgePickStatus::invalid_input:
                return carto::studio::LoopCutEdgePickStatus::invalid;
            }
            return carto::studio::LoopCutEdgePickStatus::invalid;
        }();
        bool edge_source_found = !perspective_camera_active;
        bool frontmost = true;
        std::string depth_diagnostic;
        if (perspective_camera_active) {
            const auto edge = std::find_if(native_viewport_hits.edges.begin(),
                native_viewport_hits.edges.end(), [&pick](const auto& candidate) {
                    return candidate.object == pick.object && candidate.edge == pick.edge;
                });
            edge_source_found = edge != native_viewport_hits.edges.end();
            if (pick_status == carto::studio::LoopCutEdgePickStatus::hit &&
                edge_source_found) {
                frontmost = viewport_edge_frontmost_at(*edge,
                    {static_cast<double>(point.x), static_cast<double>(point.y)},
                    snapshot.project_generation, snapshot.project_revision,
                    viewport, depth_diagnostic);
            }
        }
        const auto owner = std::find_if(snapshot.objects.begin(), snapshot.objects.end(),
            [&pick](const auto& candidate) {
                return candidate.object.id == pick.object;
            });
        const auto target = carto::studio::decide_loop_cut_pick_target({
            pick_status,
            perspective_camera_active,
            edge_source_found,
            frontmost,
            owner != snapshot.objects.end() && owner->object.visible &&
                !owner->object.locked && owner->object.mesh_asset.has_value(),
        }, depth_diagnostic);
        if (target.disposition == carto::studio::LoopCutPickDisposition::cancel) {
            return cancel_pick_with_error(std::string(target.message));
        }
        if (target.disposition == carto::studio::LoopCutPickDisposition::keep_armed) {
            return keep_pick_active_with_error(std::string(target.message));
        }
        if (target.disposition != carto::studio::LoopCutPickDisposition::admit) {
            return false;
        }
        if (!dispatch(SelectEdgeAction{
                pick.object, pick.edge, carto::editor::SelectionOperation::replace})) {
            return true;
        }
        mesh_loop_cut_seed_pick_active = false;
        const auto selected = ui.snapshot();
        if (selected.project_generation != snapshot.project_generation ||
            selected.project_revision != snapshot.project_revision ||
            selected.selection.mode != carto::editor::SelectionMode::edge ||
            selected.selection.component_groups.size() != 1U ||
            selected.selection.component_groups.front().object != pick.object ||
            selected.selection.component_groups.front().edges.size() != 1U ||
            selected.selection.component_groups.front().edges.front() != pick.edge) {
            return cancel_pick_with_error(
                "Loop cut pick selection changed before the tool could run.");
        }
        static_cast<void>(dispatch(carto::application::InvokeToolAction{
            "mesh.loop-cut", {}}));
        return true;
    }

    bool route_native_decal_placement(const carto::ui::NativePointerEvent& event) {
        if (event.button != carto::ui::NativePointerButton::primary || !event.pressed) {
            return false;
        }
        const auto keep_armed_with_error = [this](std::string message) {
            action_feedback = std::move(message);
            action_feedback_error = true;
            return true;
        };
        const auto cancel_with_error = [this](std::string message) {
            decal_placement_armed = false;
            decal_placement_target = {};
            action_feedback = std::move(message);
            action_feedback_error = true;
            return true;
        };
        const auto snapshot = ui.snapshot();
        if (surface != ShellSurface::workspace ||
            snapshot.workspace_kind != carto::ui::Workspace::model ||
            snapshot.selection.mode != carto::editor::SelectionMode::object ||
            snapshot.selection.objects.size() != 1U ||
            snapshot.selection.objects.front() != decal_placement_target) {
            return cancel_with_error(
                "Decal placement cancelled because its modeling selection changed.");
        }
        if (snapshot.project_generation != decal_placement_project_generation ||
            snapshot.project_generation != native_viewport_hits.project_generation ||
            snapshot.project_revision != decal_placement_project_revision ||
            snapshot.project_revision != native_viewport_hits.project_revision) {
            return cancel_with_error(
                "Decal placement cancelled because its project snapshot is stale.");
        }
        const auto current_source = snapshot.agent_task.has_value() && agent_preview_mode != 0
            ? carto::ui::ViewportSceneSource::agent_preview
            : carto::ui::ViewportSceneSource::live_project;
        if (current_source != carto::ui::ViewportSceneSource::live_project ||
            native_viewport_hits.scene_source != current_source) {
            return cancel_with_error(
                "Decal placement requires the current live project viewport source.");
        }
        if (!native_viewport_hits.valid || !native_viewport_hits.interactive) {
            return keep_armed_with_error(
                "Decal placement needs an interactive viewport; turn off Pan view or preview mode.");
        }
        if (native_viewport_hits.sculpt_triangles_truncated) {
            return keep_armed_with_error(
                "Decal placement refused because the viewport surface hit set exceeds its bound.");
        }
        if (carto::ui::selection_operation_for_native_pointer(event) !=
            std::optional<carto::editor::SelectionOperation>{
                carto::editor::SelectionOperation::replace}) {
            return keep_armed_with_error(
                "Decal placement requires an unmodified primary click.");
        }
        const ImVec2 point{static_cast<float>(event.x), static_cast<float>(event.y)};
        const ImRect viewport(
            native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        if (!viewport.Contains(point)) return false;
        const auto frontmost = carto::ui::resolve_frontmost_viewport_surface(
            native_viewport_hits.sculpt_triangles,
            {static_cast<double>(point.x), static_cast<double>(point.y)});
        if (!frontmost) return keep_armed_with_error(frontmost.error().message);
        if (frontmost.value().status == carto::ui::ProjectedSurfaceHitStatus::miss) {
            return keep_armed_with_error(
                "Decal placement found no visible mesh surface at the pointer.");
        }
        if (frontmost.value().status == carto::ui::ProjectedSurfaceHitStatus::ambiguous) {
            return keep_armed_with_error(
                "Decal placement refused overlapping equal-depth surfaces.");
        }
        if (frontmost.value().object != decal_placement_target) {
            return keep_armed_with_error(
                "Decal placement refused because another visible object is in front of the selected mesh.");
        }
        const auto frame = sample_native_decal_surface(
            native_viewport_hits.sculpt_triangles, decal_placement_target,
            {static_cast<double>(point.x), static_cast<double>(point.y)});
        if (!frame) return keep_armed_with_error(frame.error().message);

        const auto placement = ui.make_decal_placement(
            decal_placement_target, decal_placement_material_id,
            frame.value().center, frame.value().normal, frame.value().tangent,
            decal_placement_width, decal_placement_height, decal_placement_depth,
            0.0, snapshot.project_revision);
        if (!placement) {
            if (placement.error().code == carto::core::ErrorCode::stale_data) {
                return cancel_with_error(placement.error().message);
            }
            return keep_armed_with_error(placement.error().message);
        }
        if (!native_viewport_hits.decal_target_instance.has_value()) {
            return cancel_with_error("Decal placement lost its displayed source mesh.");
        }
        const auto action = ui.prepare_viewport_decal_placement(
            placement.value(),
            carto::ui::ViewportDecalObservation{
                native_viewport_hits.scene_source,
                native_viewport_hits.project_generation,
                native_viewport_hits.project_revision,
                *native_viewport_hits.decal_target_instance},
            current_source);
        if (!action) return keep_armed_with_error(action.error().message);
        if (!dispatch(action.value())) return true;
        decal_placement_armed = false;
        decal_placement_target = {};
        action_feedback = "Placed a revisioned decal on the exact selected mesh source.";
        action_feedback_error = false;
        return true;
    }

    bool route_native_pointer(const carto::ui::NativePointerEvent& event) {
        if (mesh_loop_cut_seed_pick_active) {
            return route_native_loop_cut_seed_pick(event);
        }
        if (decal_placement_armed) {
            return route_native_decal_placement(event);
        }
        const auto selection_operation =
            carto::ui::selection_operation_for_native_pointer(event);
        if (!selection_operation.has_value() || surface != ShellSurface::workspace ||
            !native_viewport_hits.valid || !native_viewport_hits.interactive) {
            return false;
        }
        const auto snapshot = ui.snapshot();
        if (snapshot.project_generation != native_viewport_hits.project_generation ||
            snapshot.project_revision != native_viewport_hits.project_revision) return false;

        const ImVec2 point{
            static_cast<float>(event.x),
            static_cast<float>(event.y),
        };
        const ImRect viewport(
            native_viewport_hits.screen_origin,
            native_viewport_hits.screen_origin + native_viewport_hits.extent);
        if (!viewport.Contains(point)) return false;

        if (begin_native_condition_gizmo_drag(event, snapshot, point)) return true;
        if (begin_native_transform_drag(event, snapshot, point)) return true;

        std::optional<carto::ui::ProjectedSurfaceHitResolution> perspective_surface_hit;
        if (perspective_camera_active) {
            if (native_viewport_hits.sculpt_triangles_truncated) {
                action_feedback =
                    "Perspective selection is unavailable because the visible hit set exceeds its bound.";
                action_feedback_error = true;
                if (agent_ghost_edit_mode && agent_preview_mode == 2) {
                    agent_ghost_selected_object = {};
                }
                return true;
            }
            const bool allow_same_object_face_ties =
                snapshot.selection.mode != carto::editor::SelectionMode::face ||
                (agent_ghost_edit_mode && agent_preview_mode == 2);
            const auto resolved = carto::ui::resolve_frontmost_viewport_surface(
                native_viewport_hits.sculpt_triangles,
                {static_cast<double>(point.x), static_cast<double>(point.y)},
                allow_same_object_face_ties);
            if (!resolved) {
                action_feedback = resolved.error().message;
                action_feedback_error = true;
                return true;
            }
            if (resolved.value().status ==
                carto::ui::ProjectedSurfaceHitStatus::ambiguous) {
                action_feedback =
                    "Perspective selection is ambiguous across overlapping visible surfaces.";
                action_feedback_error = true;
                if (agent_ghost_edit_mode && agent_preview_mode == 2) {
                    agent_ghost_selected_object = {};
                }
                return true;
            }
            if (resolved.value().status == carto::ui::ProjectedSurfaceHitStatus::hit) {
                perspective_surface_hit = resolved.value();
            }
        }

        if (agent_ghost_edit_mode && agent_preview_mode == 2 &&
            snapshot.agent_task.has_value() &&
            snapshot.project_revision == snapshot.agent_task->base_revision) {
            agent_ghost_selected_object = {};
            if (perspective_camera_active) {
                if (perspective_surface_hit.has_value()) {
                    const auto object = perspective_surface_hit->object;
                    const auto& task = *snapshot.agent_task;
                    const bool in_scope = std::find(task.scope_objects.begin(),
                        task.scope_objects.end(), object) != task.scope_objects.end();
                    const bool protected_object = std::find(task.protected_objects.begin(),
                        task.protected_objects.end(), object) != task.protected_objects.end();
                    if (in_scope && !protected_object) agent_ghost_selected_object = object;
                }
                return true;
            }
            for (auto iterator = native_viewport_hits.objects.rbegin();
                 iterator != native_viewport_hits.objects.rend(); ++iterator) {
                if (!iterator->second.Contains(point)) continue;
                const auto& task = *snapshot.agent_task;
                const bool in_scope = std::find(task.scope_objects.begin(),
                    task.scope_objects.end(), iterator->first) != task.scope_objects.end();
                const bool protected_object = std::find(task.protected_objects.begin(),
                    task.protected_objects.end(), iterator->first) !=
                    task.protected_objects.end();
                if (in_scope && !protected_object) {
                    agent_ghost_selected_object = iterator->first;
                }
                return true;
            }
            return true;
        }

        if (perspective_camera_active) {
            if (snapshot.selection.mode == carto::editor::SelectionMode::edge) {
                if (!perspective_surface_hit.has_value()) return false;
                std::vector<ViewportEdgeHit> visible_object_edges;
                for (const auto& candidate : native_viewport_hits.edges) {
                    if (candidate.object == perspective_surface_hit->object) {
                        visible_object_edges.push_back(candidate);
                    }
                }
                const auto hit = carto::ui::resolve_projected_edge_pick(
                    visible_object_edges,
                    {static_cast<double>(point.x), static_cast<double>(point.y)});
                if (hit.status == carto::ui::ProjectedEdgePickStatus::hit) {
                    const auto edge = std::find_if(visible_object_edges.begin(),
                        visible_object_edges.end(), [&hit](const auto& candidate) {
                            return candidate.object == hit.object && candidate.edge == hit.edge;
                        });
                    if (edge == visible_object_edges.end()) return true;
                    std::string diagnostic;
                    if (!viewport_edge_frontmost_at(*edge,
                            {static_cast<double>(point.x), static_cast<double>(point.y)},
                            snapshot.project_generation, snapshot.project_revision,
                            viewport, diagnostic)) {
                        action_feedback = std::move(diagnostic);
                        action_feedback_error = true;
                        return true;
                    }
                    static_cast<void>(dispatch(SelectEdgeAction{
                        hit.object, hit.edge, *selection_operation}));
                    return true;
                }
                if (hit.status == carto::ui::ProjectedEdgePickStatus::ambiguous) {
                    action_feedback = "Perspective edge selection is ambiguous.";
                    action_feedback_error = true;
                    return true;
                }
                return false;
            }
            if (snapshot.selection.mode == carto::editor::SelectionMode::face) {
                if (!perspective_surface_hit.has_value() ||
                    !perspective_surface_hit->sample.surface_anchor.has_value()) return false;
                static_cast<void>(dispatch(SelectFaceAction{
                    perspective_surface_hit->object,
                    perspective_surface_hit->sample.surface_anchor->face,
                    *selection_operation}));
                return true;
            }
            if (snapshot.selection.mode == carto::editor::SelectionMode::vertex) {
                constexpr std::size_t kMaxPerspectiveVertexCandidates = 32U;
                std::vector<const ViewportVertexHit*> candidates;
                candidates.reserve(kMaxPerspectiveVertexCandidates);
                for (const auto& candidate : native_viewport_hits.vertices) {
                    const float dx = candidate.point.x - point.x;
                    const float dy = candidate.point.y - point.y;
                    if (dx * dx + dy * dy >= 12.0F * 12.0F) continue;
                    if (candidates.size() == kMaxPerspectiveVertexCandidates) {
                        action_feedback =
                            "Perspective vertex selection is ambiguous at this screen density.";
                        action_feedback_error = true;
                        return true;
                    }
                    candidates.push_back(&candidate);
                }
                std::stable_sort(candidates.begin(), candidates.end(),
                    [&point](const auto* first, const auto* second) {
                        const float first_x = first->point.x - point.x;
                        const float first_y = first->point.y - point.y;
                        const float second_x = second->point.x - point.x;
                        const float second_y = second->point.y - point.y;
                        return first_x * first_x + first_y * first_y <
                            second_x * second_x + second_y * second_y;
                    });
                for (const auto* candidate : candidates) {
                    const auto surface = carto::ui::resolve_frontmost_viewport_surface(
                        native_viewport_hits.sculpt_triangles,
                        {static_cast<double>(candidate->point.x),
                         static_cast<double>(candidate->point.y)}, true);
                    if (!surface || surface.value().status !=
                            carto::ui::ProjectedSurfaceHitStatus::hit ||
                        surface.value().object != candidate->object) {
                        continue;
                    }
                    const double depth_tolerance = 1.0e-8 * std::max({
                        1.0, std::abs(candidate->camera_depth),
                        std::abs(surface.value().camera_depth)});
                    if (candidate->camera_depth + depth_tolerance <
                        surface.value().camera_depth) {
                        continue;
                    }
                    static_cast<void>(dispatch(SelectVertexAction{
                        candidate->object, candidate->vertex, *selection_operation}));
                    return true;
                }
                return false;
            }
            if (perspective_surface_hit.has_value()) {
                static_cast<void>(dispatch(SelectObjectAction{
                    perspective_surface_hit->object, *selection_operation}));
                return true;
            }
            return false;
        }

        if (snapshot.selection.mode == carto::editor::SelectionMode::edge) {
            float best = 12.0F * 12.0F;
            const ViewportEdgeHit* hit = nullptr;
            for (const auto& candidate : native_viewport_hits.edges) {
                const float distance = point_segment_distance_squared(
                    point, candidate.first, candidate.second);
                if (distance < best) {
                    best = distance;
                    hit = &candidate;
                }
            }
            if (hit != nullptr) {
                static_cast<void>(dispatch(SelectEdgeAction{
                    hit->object, hit->edge, *selection_operation}));
                return true;
            }
        } else if (snapshot.selection.mode == carto::editor::SelectionMode::face) {
            for (auto iterator = native_viewport_hits.faces.rbegin();
                 iterator != native_viewport_hits.faces.rend(); ++iterator) {
                if (point_in_triangle(
                        point, iterator->points[0], iterator->points[1], iterator->points[2])) {
                    static_cast<void>(dispatch(SelectFaceAction{
                        iterator->object, iterator->face, *selection_operation}));
                    return true;
                }
            }
        } else if (snapshot.selection.mode == carto::editor::SelectionMode::vertex) {
            float best = 12.0F * 12.0F;
            const ViewportVertexHit* hit = nullptr;
        for (const auto& candidate : native_viewport_hits.vertices) {
                const float dx = candidate.point.x - point.x;
                const float dy = candidate.point.y - point.y;
                const float distance = dx * dx + dy * dy;
                if (distance < best) {
                    best = distance;
                    hit = &candidate;
                } else if (hit != nullptr && std::abs(distance - best) <= 1.0e-4F &&
                    candidate.camera_depth > hit->camera_depth) {
                    hit = &candidate;
                }
            }
            if (hit != nullptr) {
                static_cast<void>(dispatch(SelectVertexAction{
                    hit->object, hit->vertex, *selection_operation}));
                return true;
            }
        } else {
            for (auto iterator = native_viewport_hits.objects.rbegin();
                 iterator != native_viewport_hits.objects.rend(); ++iterator) {
                if (iterator->second.Contains(point)) {
                    static_cast<void>(dispatch(SelectObjectAction{
                        iterator->first, *selection_operation}));
                    return true;
                }
            }
        }
        // Empty canvas is not a selection mutation. Let ImGui receive it so
        // the work-surface camera can start a left-button background pan.
        return false;
    }

    void export_interchange(const UiSnapshot& snapshot, bool binary_container) {
        if (!snapshot.project_path.has_value()) {
            MessageBoxW(window, L"Save the .carto project before exporting a glTF asset.",
                        L"Cartographer export unavailable", MB_OK | MB_ICONWARNING);
            return;
        }
        if (snapshot.dirty) {
            MessageBoxW(window, L"Save the project before exporting so the derived asset has a durable source revision.",
                        L"Cartographer export unavailable", MB_OK | MB_ICONWARNING);
            return;
        }
        const auto path = choose_file(true,
            binary_container ? FileDialogKind::glb : FileDialogKind::gltf);
        if (!path.has_value()) return;
        carto::providers::Registry providers;
        if (auto result = carto::io::register_builtin_gltf_providers(providers); !result) {
            MessageBoxW(window, wide(result.error().message).c_str(),
                        L"Cartographer exporter unavailable", MB_OK | MB_ICONERROR);
            return;
        }
        const auto capability = binary_container
            ? "geometry.export.glb"
            : "geometry.export.gltf";
        if (auto result = providers.resolve(capability); !result) {
            MessageBoxW(window, wide(result.error().message).c_str(),
                        L"Cartographer exporter unavailable", MB_OK | MB_ICONERROR);
            return;
        }
        const auto document = carto::project::ProjectDocument::load(*snapshot.project_path);
        if (!document) {
            MessageBoxW(window, wide(document.error().message).c_str(),
                        L"Cartographer export failed", MB_OK | MB_ICONERROR);
            return;
        }
        const auto report = binary_container
            ? carto::io::export_glb(document.value(), *path)
            : carto::io::export_gltf(document.value(), *path);
        if (!report) {
            MessageBoxW(window, wide(report.error().message).c_str(),
                        L"Cartographer export failed", MB_OK | MB_ICONERROR);
            return;
        }
        const std::string message = carto::desktop::interchange_export_feedback(report.value());
        MessageBoxW(window, wide(message).c_str(),
                    binary_container ? L"Cartographer GLB export" : L"Cartographer glTF export",
                    MB_OK | (report.value().warnings.empty() ? MB_ICONINFORMATION : MB_ICONWARNING));
    }

    void prepare_content(const UiSnapshot& snapshot, bool selected_only) {
        if (preparation_job != nullptr &&
            !carto::production::preparation_job_state_is_terminal(
                preparation_job->snapshot().state)) {
            MessageBoxW(window,
                        L"A preparation operation is already running. Cancel it or wait for its receipt before starting another.",
                        L"Cartographer preparation active", MB_OK | MB_ICONINFORMATION);
            return;
        }
        if (!snapshot.project_path.has_value()) {
            MessageBoxW(window, L"Save the .carto project before preparing content.",
                        L"Cartographer preparation unavailable", MB_OK | MB_ICONWARNING);
            return;
        }
        if (snapshot.dirty) {
            MessageBoxW(window,
                        L"Save the project before preparation so every product is bound to one durable source revision.",
                        L"Cartographer preparation unavailable", MB_OK | MB_ICONWARNING);
            return;
        }
        const auto document = carto::project::ProjectDocument::load(
            snapshot.project_path.value());
        if (!document) {
            MessageBoxW(window, wide(document.error().message).c_str(),
                        L"Cartographer preparation failed", MB_OK | MB_ICONERROR);
            return;
        }

        carto::production::PreparationScopeRequest scope;
        scope.expected_source_revision = document.value().revision();
        if (selected_only) {
            scope.kind = carto::production::PreparationScopeKind::selection;
            scope.node_ids.reserve(snapshot.selection.objects.size() + 1U);
            for (const auto object : snapshot.selection.objects) {
                scope.node_ids.push_back(object.value);
            }
            if (snapshot.selection.component_object.has_value()) {
                scope.node_ids.push_back(snapshot.selection.component_object->value);
            }
            std::sort(scope.node_ids.begin(), scope.node_ids.end());
            scope.node_ids.erase(
                std::unique(scope.node_ids.begin(), scope.node_ids.end()),
                scope.node_ids.end());
            if (scope.node_ids.empty()) {
                MessageBoxW(window, L"Select at least one scene object to prepare a selection.",
                            L"Cartographer preparation scope", MB_OK | MB_ICONWARNING);
                return;
            }
        } else {
            scope.kind = carto::production::PreparationScopeKind::scene;
        }

        const std::filesystem::path output_root{
            snapshot.project_path->string() + ".prepared"};
        const auto current = carto::production::read_selected_prepared_scene(output_root);
        if (!current) {
            MessageBoxW(window, wide(current.error().message).c_str(),
                        L"Cartographer preparation baseline invalid", MB_OK | MB_ICONERROR);
            return;
        }
        std::optional<carto::assets::Sha256Digest> expected;
        if (current.value().has_value()) {
            expected = current.value()->prepared_scene_digest;
        }
        auto source_root = snapshot.project_path->parent_path();
        if (source_root.empty()) source_root = std::filesystem::current_path();
        const carto::production::PreparationOperationRequest request{
            .scope = std::move(scope),
            .profile = carto::production::portable_preparation_profile(),
            .source_root = std::move(source_root),
            .output_root = output_root,
            .expected_selected_digest = expected,
            .stop_token = {},
        };
        auto started = carto::production::PreparationJob::start(
            document.value(), request);
        if (!started) {
            MessageBoxW(window, wide(started.error().message).c_str(),
                        L"Cartographer preparation failed", MB_OK | MB_ICONERROR);
            return;
        }
        preparation_job = std::move(started.value());
    }

    void poll_preparation_job() {
        if (preparation_job == nullptr) return;
        const auto status = preparation_job->snapshot();
        if (!carto::production::preparation_job_state_is_terminal(status.state)) return;

        preparation_job->wait();
        const auto report = preparation_job->report();
        preparation_job.reset();
        if (!report.has_value()) {
            MessageBoxW(window, L"Preparation ended without a terminal receipt.",
                        L"Cartographer preparation failed", MB_OK | MB_ICONERROR);
            return;
        }
        if (!report->succeeded()) {
            std::string message = "Preparation ended as " +
                std::string(carto::production::preparation_job_state_name(status.state)) + ".";
            for (const auto& diagnostic : report->diagnostics) {
                message += "\n\n" + diagnostic.code + "\n" + diagnostic.message;
                if (diagnostic.source_primary.has_value()) {
                    message += "\nSource " +
                        std::to_string(diagnostic.source_primary.value());
                }
                if (message.size() > 6'000U) break;
            }
            const UINT icon = status.state ==
                    carto::production::PreparationJobState::cancelled
                ? MB_ICONINFORMATION
                : MB_ICONERROR;
            MessageBoxW(window, wide(message).c_str(),
                        L"Cartographer preparation", MB_OK | icon);
            return;
        }
        std::string message =
            "Prepared " + std::to_string(report->resolved_scope->asset_ids.size()) +
            " asset(s), " + std::to_string(report->resolved_scope->node_ids.size()) +
            " node(s), and " + std::to_string(report->envelope->products.size()) +
            " verified product(s).\n\nRevision " +
            report->publication->prepared_scene_digest.hex() + "\n" +
            report->publication->revision_path.string();
        if (!report->diagnostics.empty()) {
            message += "\n\nCompleted with " +
                std::to_string(report->diagnostics.size()) + " warning(s).";
        }
        MessageBoxW(window, wide(message).c_str(),
                    L"Cartographer preparation complete", MB_OK | MB_ICONINFORMATION);
    }

    void export_standard_mesh(const UiSnapshot& snapshot, StandardMeshExport format) {
        if (!snapshot.project_path.has_value()) {
            MessageBoxW(window, L"Save the .carto project before exporting a mesh asset.",
                        L"Cartographer export unavailable", MB_OK | MB_ICONWARNING);
            return;
        }
        if (snapshot.dirty) {
            MessageBoxW(window, L"Save the project before exporting so the derived asset has a durable source revision.",
                        L"Cartographer export unavailable", MB_OK | MB_ICONWARNING);
            return;
        }
        const FileDialogKind dialog_kind = format == StandardMeshExport::obj
            ? FileDialogKind::obj
            : format == StandardMeshExport::ply ? FileDialogKind::ply : FileDialogKind::stl;
        const auto path = choose_file(true, dialog_kind);
        if (!path.has_value()) return;

        carto::providers::Registry providers;
        const auto register_provider = [&]() -> carto::core::Result<void> {
            if (format == StandardMeshExport::obj) return carto::io::register_builtin_obj_providers(providers);
            if (format == StandardMeshExport::ply) return carto::io::register_builtin_ply_providers(providers);
            return carto::io::register_builtin_stl_providers(providers);
        };
        const char* capability = format == StandardMeshExport::obj
            ? "geometry.export.obj"
            : format == StandardMeshExport::ply ? "geometry.export.ply" : "geometry.export.stl";
        if (auto result = register_provider(); !result) {
            MessageBoxW(window, wide(result.error().message).c_str(),
                        L"Cartographer exporter unavailable", MB_OK | MB_ICONERROR);
            return;
        }
        if (auto result = providers.resolve(capability); !result) {
            MessageBoxW(window, wide(result.error().message).c_str(),
                        L"Cartographer exporter unavailable", MB_OK | MB_ICONERROR);
            return;
        }
        const auto document = carto::project::ProjectDocument::load(*snapshot.project_path);
        if (!document) {
            MessageBoxW(window, wide(document.error().message).c_str(),
                        L"Cartographer export failed", MB_OK | MB_ICONERROR);
            return;
        }
        std::vector<std::uint64_t> selected_nodes;
        selected_nodes.reserve(snapshot.selection.objects.size() + 1U);
        for (const auto object : snapshot.selection.objects) {
            selected_nodes.push_back(object.value);
        }
        if (snapshot.selection.component_object.has_value()) {
            selected_nodes.push_back(snapshot.selection.component_object->value);
        }
        std::sort(selected_nodes.begin(), selected_nodes.end());
        selected_nodes.erase(
            std::unique(selected_nodes.begin(), selected_nodes.end()),
            selected_nodes.end());

        carto::core::Result<std::uint64_t> resolved_mesh =
            carto::production::resolve_single_mesh_export(document.value(), std::nullopt);
        if (!selected_nodes.empty()) {
            const auto scope = carto::production::resolve_preparation_scope(
                document.value(), carto::production::PreparationScopeRequest{
                    carto::production::PreparationScopeKind::selection,
                    snapshot.project_revision,
                    {},
                    selected_nodes,
                });
            if (!scope) {
                MessageBoxW(window, wide(scope.error().message).c_str(),
                            L"Cartographer export scope invalid", MB_OK | MB_ICONWARNING);
                return;
            }
            if (scope.value().asset_ids.size() != 1U) {
                MessageBoxW(window,
                            L"Select objects that resolve to exactly one reusable mesh asset.",
                            L"Cartographer export scope ambiguous", MB_OK | MB_ICONWARNING);
                return;
            }
            resolved_mesh = carto::core::Result<std::uint64_t>::success(
                scope.value().asset_ids.front());
        }
        if (!resolved_mesh) {
            MessageBoxW(window, wide(resolved_mesh.error().message).c_str(),
                        L"Cartographer export scope required", MB_OK | MB_ICONWARNING);
            return;
        }
        const auto export_mesh = [&]() -> carto::core::Result<carto::io::IoReport> {
            const auto& mesh = document.value().meshes().at(resolved_mesh.value());
            if (format == StandardMeshExport::obj) return carto::io::export_obj(mesh, *path);
            if (format == StandardMeshExport::ply) return carto::io::export_ply(mesh, *path);
            return carto::io::export_stl(mesh, *path);
        };
        const auto report = export_mesh();
        if (!report) {
            MessageBoxW(window, wide(report.error().message).c_str(),
                        L"Cartographer export failed", MB_OK | MB_ICONERROR);
            return;
        }
        const std::string message = "Exported " + path->string() + "\n" +
            "Mesh asset " + std::to_string(resolved_mesh.value()) + ", " +
            std::to_string(report.value().vertices) + " vertex/vertices, " +
            std::to_string(report.value().triangles) + " triangle(s).";
        MessageBoxW(window, wide(message).c_str(),
                    L"Cartographer mesh export", MB_OK | MB_ICONINFORMATION);
    }

    void recover_latest_snapshot(const UiSnapshot& snapshot) {
        std::optional<std::filesystem::path> path = snapshot.project_path;
        if (!path.has_value()) path = choose_file(false, FileDialogKind::project);
        if (!path.has_value()) return;

        const auto inspection = ApplicationSession::inspect_recovery(*path);
        if (!inspection) {
            MessageBoxW(window, wide(inspection.error().message).c_str(),
                        L"Cartographer recovery unavailable", MB_OK | MB_ICONERROR);
            return;
        }
        if (inspection.value().state ==
            carto::application::RecoveryInspectionState::blocked) {
            const std::string message = inspection.value().diagnostic.has_value()
                ? inspection.value().diagnostic->message
                : "durable recovery evidence is blocked";
            MessageBoxW(window, wide(message).c_str(),
                        L"Cartographer recovery blocked", MB_OK | MB_ICONERROR);
            return;
        }
        if (inspection.value().state !=
            carto::application::RecoveryInspectionState::pending) {
            MessageBoxW(window,
                        L"No pending journal snapshot is available for this project.",
                        L"Cartographer recovery", MB_OK | MB_ICONINFORMATION);
            return;
        }

        carto::application::RecoverProjectAction action{*path};
        if (snapshot.dirty) {
            action.discard_dirty = true;
            request_discard(std::move(action));
        } else {
            static_cast<void>(dispatch(action));
        }
    }

    void request_discard(carto::application::ApplicationAction action) {
        pending_discard_action = std::move(action);
        pending_exit = false;
        discard_prompt_pending = true;
    }

    void request_close() noexcept { close_requested = true; }

    void approve_close() noexcept {
        PostQuitMessage(0);
    }

    void process_close_request() {
        if (!close_requested) return;
        close_requested = false;
        if (ui.can_close()) {
            approve_close();
            return;
        }
        pending_discard_action.reset();
        pending_exit = true;
        discard_prompt_pending = true;
    }

    void draw_discard_prompt() {
        if (discard_prompt_pending) {
            ImGui::OpenPopup("Discard Unsaved Changes");
            discard_prompt_pending = false;
        }
        if (!ImGui::BeginPopupModal(
                "Discard Unsaved Changes", nullptr, ImGuiWindowFlags_AlwaysAutoResize)) {
            return;
        }
        ImGui::TextUnformatted("This project has unsaved changes.");
        ImGui::TextUnformatted("Discard them and continue?");
        if (ImGui::Button("Discard", ImVec2(120, 0))) {
            if (pending_exit) {
                pending_exit = false;
                pending_discard_action.reset();
                ImGui::CloseCurrentPopup();
                approve_close();
            } else if (pending_discard_action.has_value()) {
                auto action = std::move(*pending_discard_action);
                pending_discard_action.reset();
                ImGui::CloseCurrentPopup();
                static_cast<void>(dispatch(action));
            }
        }
        ImGui::SameLine();
        if (ImGui::Button("Keep Editing", ImVec2(120, 0))) {
            pending_exit = false;
            pending_discard_action.reset();
            ImGui::CloseCurrentPopup();
        }
        ImGui::EndPopup();
    }

    [[nodiscard]] bool has_pane(const ApplicationSnapshot& snapshot, carto::application::Pane pane) const {
        return std::find(
            snapshot.workspace.visible_panes.begin(),
            snapshot.workspace.visible_panes.end(),
            pane) != snapshot.workspace.visible_panes.end();
    }

    [[nodiscard]] static std::optional<carto::ui::Panel> ui_panel(
        carto::application::Pane pane) noexcept {
        switch (pane) {
        case carto::application::Pane::outliner: return carto::ui::Panel::scene;
        case carto::application::Pane::viewport: return carto::ui::Panel::viewport;
        case carto::application::Pane::inspector: return carto::ui::Panel::inspector;
        case carto::application::Pane::problems: return carto::ui::Panel::problems;
        case carto::application::Pane::history: return carto::ui::Panel::operations;
        }
        return std::nullopt;
    }

    void toggle_pane(const UiSnapshot& snapshot, carto::application::Pane pane) {
        if (pane == carto::application::Pane::viewport) return;
        const auto panel = ui_panel(pane);
        if (!panel.has_value()) return;
        const bool visible = std::find(
            snapshot.visible_panels.begin(), snapshot.visible_panels.end(), *panel) !=
            snapshot.visible_panels.end();
        static_cast<void>(ui.set_panel_visible(*panel, !visible));
    }

    [[nodiscard]] static ImVec4 color(carto::ui::UiColor value) noexcept {
        return ImVec4(value.red, value.green, value.blue, value.alpha);
    }

    void apply_theme(const UiSnapshot& snapshot) {
        carto::studio::apply_studio_style(snapshot);
    }

    void apply_window_chrome(const UiSnapshot& snapshot) {
        if (window == nullptr || applied_window_theme == snapshot.theme) return;
        const BOOL dark_mode = snapshot.theme != carto::ui::Theme::light ? TRUE : FALSE;
        const COLORREF caption = dark_mode == TRUE ? RGB(7, 11, 18) : RGB(244, 246, 249);
        const COLORREF text = dark_mode == TRUE ? RGB(230, 236, 250) : RGB(20, 26, 36);
        // These attributes are supported by current Windows 10/11 builds. The
        // calls are intentionally best-effort so older systems keep the native
        // title bar instead of making startup fail.
        static_cast<void>(DwmSetWindowAttribute(
            window, static_cast<DWMWINDOWATTRIBUTE>(20), &dark_mode, sizeof(dark_mode)));
        static_cast<void>(DwmSetWindowAttribute(
            window, static_cast<DWMWINDOWATTRIBUTE>(35), &caption, sizeof(caption)));
        static_cast<void>(DwmSetWindowAttribute(
            window, static_cast<DWMWINDOWATTRIBUTE>(36), &text, sizeof(text)));
        applied_window_theme = snapshot.theme;
    }

    [[nodiscard]] ImVec4 status_color(const UiSnapshot& snapshot) const noexcept {
        switch (snapshot.project_status) {
        case carto::ui::ProjectStatus::unsaved:
            return color(snapshot.colors.semantic_warning);
        case carto::ui::ProjectStatus::saved:
            return color(snapshot.colors.semantic_success);
        case carto::ui::ProjectStatus::modified:
            return color(snapshot.colors.modified);
        case carto::ui::ProjectStatus::render_error:
            return color(snapshot.colors.semantic_warning);
        case carto::ui::ProjectStatus::ui_error:
            return color(snapshot.colors.semantic_error);
        }
        return color(snapshot.colors.text_secondary);
    }

    [[nodiscard]] const char* surface_title() const noexcept {
        switch (surface) {
        case ShellSurface::workspace: return "Workspace";
        case ShellSurface::project: return "Project";
        case ShellSurface::market: return "Market";
        case ShellSurface::diagnostics: return "Diagnostics";
        case ShellSurface::settings: return "Settings";
        }
        return "Workspace";
    }

    [[nodiscard]] std::string project_location(const UiSnapshot& snapshot) const {
        if (!snapshot.project_path.has_value()) return "Local workspace · not saved to disk";
        return snapshot.project_path->string();
    }

    void draw_shell_header(const UiSnapshot& snapshot) {
        // At normal desktop widths the wordmark and utility controls do not
        // fit on one row. Move the controls to their own row before they are
        // clipped by the window edge; the old 900 px threshold was too low.
        const bool compact_header = ImGui::GetWindowWidth() < 1480.0F;
        ImGui::BeginChild("ShellHeader", ImVec2(0, compact_header ? 152.0F : 96.0F),
                          true, ImGuiWindowFlags_NoScrollbar);
        ImGui::BeginGroup();
        draw_brand_lockup(snapshot);
        ImGui::SameLine();
        ImGui::TextDisabled("/");
        ImGui::SameLine();
        heading_text(surface_title());
        ImGui::Text("%s", snapshot.project_name.c_str());
        mono_text_disabled(project_location(snapshot).c_str());
        ImGui::EndGroup();

        if (compact_header) ImGui::Dummy(ImVec2(0, 4));
        else ImGui::SameLine(std::max(240.0F, ImGui::GetWindowWidth() - 555.0F));
        ImGui::BeginGroup();
        const ImVec4 status = status_color(snapshot);
        ImVec4 status_surface = status;
        status_surface.w = 0.16F;
        ImGui::PushStyleColor(ImGuiCol_Button, status_surface);
        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, status_surface);
        ImGui::PushStyleColor(ImGuiCol_Text, status);
        const std::string status_label = snapshot.project_status_text + "##header-status";
        ImGui::SmallButton(status_label.c_str());
        ImGui::PopStyleColor(3);
        ImGui::SameLine();
        ImGui::TextDisabled("Appearance");
        ImGui::SameLine();
        if (snapshot.theme == carto::ui::Theme::dark) ImGui::PushStyleColor(
            ImGuiCol_Button, color(snapshot.colors.panel_selected));
        if (ImGui::SmallButton("Dark##header-theme")) {
            static_cast<void>(ui.set_theme(carto::ui::Theme::dark));
        }
        if (snapshot.theme == carto::ui::Theme::dark) ImGui::PopStyleColor();
        ImGui::SameLine();
        if (snapshot.theme == carto::ui::Theme::light) ImGui::PushStyleColor(
            ImGuiCol_Button, color(snapshot.colors.panel_selected));
        if (ImGui::SmallButton("Light##header-theme")) {
            static_cast<void>(ui.set_theme(carto::ui::Theme::light));
        }
        if (snapshot.theme == carto::ui::Theme::light) ImGui::PopStyleColor();
        ImGui::SameLine();
        if (ImGui::Button(compact_header ? "Commands" : "Command palette  Ctrl+K")) {
            static_cast<void>(ui.handle_shortcut(carto::ui::Shortcut::toggle_command_palette));
        }
        ImGui::SameLine();
        if (ImGui::Button(compact_header ? "Agent" : "Ask Cartographer…")) {
            static_cast<void>(open_agent_workspace(true));
        }
        ImGui::SameLine();
        if (ImGui::Button(compact_header ? "Flow" : "Compose")) {
            ImGui::OpenPopup("Compose workbench");
        }
        if (ImGui::BeginPopup("Compose workbench")) {
            ImGui::TextDisabled("Assemble the work surface for your flow.");
            ImGui::TextDisabled("Learns from your choices only; stays local.");
            ImGui::Separator();
            const auto remembered = remembered_workbench_flow();
            if (remembered.has_value()) {
                const std::string resume_label = "Resume " +
                    std::string(workbench_flow_name(*remembered));
                if (ImGui::MenuItem(resume_label.c_str(), "Ctrl+Shift+R")) {
                    compose_workbench_flow(*remembered);
                }
                ImGui::Separator();
            }
            for (const WorkbenchFlow flow : workbench_flow_order()) {
                std::string label = workbench_flow_name(flow);
                if (remembered.has_value() && flow == *remembered &&
                    workbench_flow_uses(flow) > 0U) {
                    label += "  · Recommended";
                }
                if (ImGui::MenuItem(label.c_str(), workbench_flow_shortcut(flow),
                                    workbench_flow == flow)) {
                    compose_workbench_flow(flow);
                }
            }
            ImGui::Separator();
            if (ImGui::MenuItem("Forget learned order")) {
                forget_workbench_flow_memory();
            }
            ImGui::EndPopup();
        }
        ImGui::SameLine();
        ImGui::TextDisabled("%s", workbench_flow_name(workbench_flow));
        ImGui::SameLine();
        if (ImGui::Button("Save")) {
            static_cast<void>(save_project(snapshot));
        }
        ImGui::EndGroup();
        ImGui::EndChild();
    }

    void draw_navigation_rail(const UiSnapshot& snapshot, float rail_width = 0.0F) {
        const float available_width = rail_width > 0.0F
            ? rail_width : ImGui::GetContentRegionAvail().x;
        const bool narrow = available_width < 220.0F;
        ImGui::BeginChild("ProductRail", ImVec2(rail_width, 0), true);
        if (narrow) {
            draw_brand_mark(snapshot, 34.0F);
            ImGui::TextDisabled("Carto");
        } else {
            draw_brand_mark(snapshot, 42.0F);
            ImGui::SameLine();
            ImGui::BeginGroup();
            heading_text("Spatial authoring");
            ImGui::TextDisabled("Geometry, history, and evidence.");
            ImGui::EndGroup();
        }
        ImGui::Dummy(ImVec2(0, 6));

        const auto nav_item = [this, &snapshot, narrow](const char* label, const char* compact_label,
                                                        const char* detail, ShellSurface target) {
            const bool selected = surface == target;
            if (selected) {
                ImGui::PushStyleColor(ImGuiCol_Header, color(snapshot.colors.panel_selected));
                ImGui::PushStyleColor(ImGuiCol_Text, color(snapshot.colors.accent_primary));
            }
            const char* shown_label = narrow ? compact_label : label;
            if (ImGui::Selectable(shown_label, selected, 0, ImVec2(0, 32))) surface = target;
            if (selected) ImGui::PopStyleColor(2);
            if (narrow && ImGui::IsItemHovered()) {
                ImGui::BeginTooltip();
                ImGui::TextUnformatted(label);
                ImGui::TextDisabled("%s", detail);
                ImGui::EndTooltip();
            } else if (!narrow) {
                ImGui::TextDisabled("  %s", detail);
            }
        };
        nav_item("Workspace", "W", "Author geometry", ShellSurface::workspace);
        nav_item("Project", "P", "Persistence and revision", ShellSurface::project);
        nav_item("Market", "M", "Local data packages", ShellSurface::market);
        nav_item("Diagnostics", "D", "Problems and capability", ShellSurface::diagnostics);
        nav_item("Settings", "S", "Density, theme, operator", ShellSurface::settings);

        ImGui::Spacing();
        if (ImGui::Button(narrow ? "+" : "+  New Project", ImVec2(-1, 34))) {
            carto::application::NewProjectAction action{"Untitled"};
            if (snapshot.dirty) {
                action.discard_dirty = true;
                request_discard(std::move(action));
            } else {
                static_cast<void>(dispatch(action));
            }
        }
        if (ImGui::Button(narrow ? "Open" : "Open Project", ImVec2(-1, 30))) {
            if (const auto path = choose_file(false); path.has_value()) {
                carto::application::OpenProjectAction action{*path};
                if (snapshot.dirty) {
                    action.discard_dirty = true;
                    request_discard(std::move(action));
                } else {
                    static_cast<void>(dispatch(action));
                }
            }
        }

        ImGui::Dummy(ImVec2(0, 8));
        ImGui::Separator();
        ImGui::TextDisabled(narrow ? "State" : "Session");
        if (narrow) {
            ImGui::Text("R%llu", static_cast<unsigned long long>(snapshot.project_revision.value()));
            ImGui::Text("%zu obj", snapshot.objects.size());
            ImGui::TextColored(status_color(snapshot), "%s", snapshot.dirty ? "●" : "○");
            ImGui::Spacing();
            ImGui::TextColored(renderer_ready ? color(snapshot.colors.semantic_success)
                                              : color(snapshot.colors.semantic_error),
                              renderer_ready ? "●" : "×");
        } else {
            ImGui::Text("Revision %llu", static_cast<unsigned long long>(snapshot.project_revision.value()));
            ImGui::Text("%zu object%s", snapshot.objects.size(), snapshot.objects.size() == 1U ? "" : "s");
            ImGui::TextColored(status_color(snapshot), "%s", snapshot.project_status_text.c_str());
            if (snapshot.dirty) ImGui::TextColored(color(snapshot.colors.modified), "Unsaved changes");
            ImGui::Spacing();
            ImGui::TextDisabled("Native shell");
            ImGui::TextColored(renderer_ready ? color(snapshot.colors.semantic_success)
                                              : color(snapshot.colors.semantic_error),
                              renderer_ready ? "Active" : "Unavailable");
            ImGui::TextDisabled("Mutations remain behind the application session.");
        }
        ImGui::EndChild();
    }

    void rack_button(const UiSnapshot& snapshot,
                     carto::ui::WorkbenchInstrument instrument,
                     const char* label, bool& open) {
        ImGui::PushID(static_cast<int>(instrument));
        const bool selected = open;
        if (selected) {
            ImGui::PushStyleColor(ImGuiCol_Button, color(snapshot.colors.panel_selected));
            ImGui::PushStyleColor(ImGuiCol_Text, color(snapshot.colors.accent_primary));
        }
        const bool placing = workbench.placement_mode == instrument;
        const float available_width = ImGui::GetContentRegionAvail().x;
        const float grip_width = std::min(68.0F,
            std::max(52.0F, available_width * 0.40F));
        const float row_height = 34.0F;
        const float row_spacing = 2.0F;
        const float label_width = std::max(1.0F,
            available_width - grip_width - row_spacing);
        const auto add_drag_source = [instrument, label]() {
            if (!ImGui::BeginDragDropSource()) return;
            const int instrument_index = static_cast<int>(instrument);
            ImGui::SetDragDropPayload(
                "CARTO_WORKBENCH_INSTRUMENT", &instrument_index,
                static_cast<int>(sizeof(instrument_index)));
            ImGui::Text("Place %s", label);
            ImGui::EndDragDropSource();
        };
        if (ImGui::Button(label, ImVec2(label_width, row_height))) {
            open = !open;
            mark_custom_workbench();
        }
        const ImVec2 row_min = ImGui::GetItemRectMin();
        add_drag_source();
        if (selected) ImGui::PopStyleColor(2);
        ImGui::SameLine(0.0F, row_spacing);
        if (placing) {
            ImGui::PushStyleColor(ImGuiCol_Button,
                                  color(snapshot.colors.panel_selected));
            ImGui::PushStyleColor(ImGuiCol_Text,
                                  color(snapshot.colors.accent_primary));
        }
        if (ImGui::Button("MOVE", ImVec2(grip_width, row_height))) {
            open = true;
            workbench.placement_mode = placing
                ? std::nullopt
                : std::optional<carto::ui::WorkbenchInstrument>{instrument};
            mark_custom_workbench();
        }
        const bool move_hovered = ImGui::IsItemHovered();
        const ImVec2 grip_max = ImGui::GetItemRectMax();
        add_drag_source();
        if (placing) ImGui::PopStyleColor(2);
        const bool row_hovered = ImGui::IsMouseHoveringRect(row_min, grip_max, true);
        if (move_hovered) {
            ImGui::SetTooltip(placing
                ? "Click the work surface to place %s; press Escape to cancel."
                : "Click, then click the work surface to place %s; dragging still works.",
                label);
        } else if (row_hovered) {
            ImGui::SetTooltip("Click to open or close %s; drag the row or use MOVE to place it.",
                              label);
        }
        ImGui::PopID();
    }

